# Generated from tools/data/rulebooks/rummy.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Rummy
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:table, GameRoomRules.translate("Turn a hand of cards into combinations"),
            GameRoomRules.translate("Rummy is a game for two to eight players. Each receives fourteen cards. Two decks are used for two to four players, three for five or six, and four for seven or eight; every deck includes two jokers. The Identities option always uses four decks. Your main task is to place cards in valid combinations and eventually empty your hand."),
            GameRoomRules.translate("Normally you begin your turn by drawing, then may make several combinations, add cards to combinations already on the table or carry out permitted manipulations. Discarding one card ends the turn. In No discard mode, finish without discarding. You cannot work on the table before drawing, except when no source of cards remains. Emptying your hand ends the round immediately: you do not need to keep an extra card just to discard it.")),
          rule_section(:combinations, GameRoomRules.translate("Runs, sets and the position of a joker"),
            GameRoomRules.translate("A run contains at least three consecutive cards of the same suit, placed in ascending order. For example, 6, 7 and 8 of hearts is a run; three sevens of different suits are not. An ace may come before 2 or after king, so A-2-3 and Q-K-A are valid, but K-A-2 is not. A set contains three or four cards of the same rank in different suits."),
            GameRoomRules.translate("Each combination may contain at most one joker and must have at least two natural cards. A joker fills the missing position, but is still read aloud as joker so you can locate it. Selection order matters: joker, 3, 4 of spades means a low run, whereas 3, 4 of spades, joker ends with a five. The game does not rearrange a selected packet to guess what you intended."),
            GameRoomRules.translate("Identities, off by default, also permits three or four identical cards: the same rank and suit from different decks. This is different from an ordinary set, whose suits must differ. An identity combination gains an extra 10 points per card when scoring melds; the elimination mode still does not award points for melds.")),
          rule_section(:opening, GameRoomRules.translate("Your first meld opens access to the table"),
            GameRoomRules.translate("At the start of each round, everyone must make their own first meld. Its minimum value defaults to 30 points and can be set from 15 to 90. You may prepare several new combinations from your own hand and submit them together to reach that value. A single combination below the threshold is not enough just because you hope to add another later."),
            GameRoomRules.translate("Until that first meld is accepted, you cannot draw from the discard pile, add to existing combinations, recover jokers or take and merge combinations. Once you have opened, you may use other players' combinations as well as your own. This permission resets with the next round.")),
          rule_section(:discard, GameRoomRules.translate("Choose how the discard pile works"),
            GameRoomRules.translate("No discard mode removes discarding and drawing from discards. Discard only lets players discard at the end of a turn, but nobody may take those cards. Single discard, the default, lets an eligible player draw the top discarded card instead of drawing from the stock. Only that top card is available to inspect in this mode."),
            GameRoomRules.translate("Multiple discard shows the pile with the newest card first. Choosing a card also takes every newer card above it: the third item takes the third, second and first cards. You may retain discarded cards in your hand; drawing one does not require immediate use. When the stock runs out, older discards can be shuffled into it while the top discard remains on the table.")),
          rule_section(:joker, GameRoomRules.translate("Recover a joker by replacing it"),
            GameRoomRules.translate("A joker in your hand cannot be added directly to an existing combination. Use it when making a new combination with at least two natural cards. With manipulations enabled, those cards may include ones you have legally taken from the table. This restriction also matters after recovering a joker: having somewhere to put a normal card does not necessarily give you somewhere to put the joker."),
            GameRoomRules.translate("After your first meld, you can recover a table joker by playing the natural card needed in its place. This is a use of the replacement card, not a separate command on the joker. In a three-card set with two natural suits and a joker, first add a third natural suit; the remaining fourth suit can then replace the joker. You cannot simply pull out a joker and leave an invalid combination behind."),
            GameRoomRules.translate("A recovered joker is a borrowed table card. Play it back onto the table before ending your turn to avoid a 300-point penalty. You may keep it instead and accept that penalty. The same rule applies to other borrowed cards in the manipulation variant. Discarding a borrowed card does not count as playing it back.")),
          rule_section(:manipulation, GameRoomRules.translate("Taking and merging table combinations"),
            GameRoomRules.translate("Combination manipulations is off by default. With it enabled, and after drawing and completing your first meld, you may take a whole combination without a joker, remove an end card from a run or a card from a set if what remains is still valid, and merge compatible combinations. The remaining combination must still contain at least three cards; existing joker assignments cannot silently change. To take a whole combination containing a joker, recover the joker first."),
            GameRoomRules.translate("You need not return every borrowed card, but each one left unplayed at the end of the turn costs 300 points. Two retained cards therefore cost 600. This is charged once; on later turns those cards are ordinary hand cards. An equivalent copy can repay one borrowed card, not several. In normal scoring, taking a card also removes its previous meld value; putting it back awards its new meld value. Moving cards around is not a source of free repeated points.")),
          rule_section(:values, GameRoomRules.translate("Card values and rounding"),
            GameRoomRules.translate("Rounding scores to units of five is on by default. With it, cards 2\u20139 are worth 5, and 10, jack, queen and king are worth 10. An ace before 2 is worth 5; a high ace or an ace in a set is worth 15. Without rounding, 2\u20139 use their printed values, face cards and 10 are worth 10, a low ace is worth 1 and a high or set ace 11. An ace left in your hand uses the high value."),
            GameRoomRules.translate("A played joker scores as the card it represents; a joker left in the hand is worth 20. For example, with rounding, a run of 3, 4 and joker scores 15 because it represents 3-4-5. The same card values are used when checking your first meld and counting unfinished hands.")),
          rule_section(:normal, GameRoomRules.translate("Normal scoring rewards what you lay down"),
            GameRoomRules.translate("In either scoring mode, the score limit can be any whole number from 1 to 100000. Changing it alters when the match ends, not the values of cards or penalties."),
            GameRoomRules.translate("In normal mode, earn points for your melded and laid-off cards. The player who empties their hand also receives the value of the cards remaining in the other hands. Finishing in the same turn as your first meld is a rummy: it adds 200 points, or 300 instead if you use only your own hand without laying off or borrowing from the table. Doing this before anyone else has made a first meld adds another 100."),
            GameRoomRules.translate("Penalties subtract from your score. The score limit defaults to 1000 and is checked after the round, not as soon as a meld crosses it. The highest score wins; a tied lead requires further play. If the round becomes blocked, everyone keeps the points they earned, but nobody receives the finishing bonus or the others' hand values.")),
          rule_section(:elimination, GameRoomRules.translate("Elimination reverses the aim"),
            GameRoomRules.translate("Elimination mode is an optional checkbox. Here, fewer points are better. Melds and laid-off cards earn nothing; at the end of a round everyone counts the cards still in their hand, so the finisher receives zero for cards. A rummy doubles opponents' hand values. A rummy made solely from your own hand triples them, or quadruples them if nobody else had opened. Separate penalties are not multiplied."),
            GameRoomRules.translate("The elimination limit defaults to 500. Check it after settling the whole round: reaching or exceeding it eliminates a player. If everyone would go out together, the lowest total wins, with a shared result for equal lowest scores. Normally the last player below the limit wins. A blocked round simply charges each remaining hand, without a rummy multiplier. Penalties, including 300 for an unreturned table card, add points in this mode rather than subtracting them.")),
          rule_section(:time, GameRoomRules.translate("Time limits and a blocked round"),
            GameRoomRules.translate("Thinking time is zero for unlimited play, or 20\u2013600 seconds for the entire turn. Menus and preparing combinations use that time too. On timeout you lose 50 points in normal mode or gain 50 in elimination. If you have not drawn yet, the game draws one stock card when available; it does not draw another if you already drew. Your turn then ends without a discard. Penalties for borrowed cards still apply as well."),
            GameRoomRules.translate("Two full circuits without drawing or placing an original hand card block the round. Taking cards from the table and returning them alone does not keep a round alive indefinitely. A saved game must be taken at a clean turn boundary, before drawing or manipulating combinations.")),
          rule_section(:controls, GameRoomRules.translate("Game keyboard shortcuts"),
            GameRoomRules.translate("Arrows: browse cards or combinations."),
            GameRoomRules.translate("Enter: in a draft, add the card in order; otherwise choose a matching meld or discard."),
            GameRoomRules.translate("Delete: discard the current card immediately."),
            GameRoomRules.translate("Space: draw from the stock."),
            GameRoomRules.translate("D: read visible discards without opening a list."),
            GameRoomRules.translate("Shift+D: take the sole available discard, or open the discard list."),
            GameRoomRules.translate("N: start a new combination in the draft."),
            GameRoomRules.translate("F: submit the prepared combinations."),
            GameRoomRules.translate("Shift+F: finish the turn without discarding in No discard mode."),
            GameRoomRules.translate("P: read the draft."),
            GameRoomRules.translate("Shift+P: edit the draft."),
            GameRoomRules.translate("Escape: cancel the current choice or draft."),
            GameRoomRules.translate("C: browse table combinations; their context menu contains available taking and merging actions."),
            GameRoomRules.translate("E: read card counts."),
            GameRoomRules.translate("Z: next card with a legal immediate lay-off; only a sole unambiguous addition may be automatic."),
            GameRoomRules.translate("Shift+Z: previous card with a legal immediate lay-off; only a sole unambiguous addition may be automatic."),
            GameRoomRules.translate("S: read scores."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("Shift+C: sort by suit or colour; press again to reverse the order."),
            GameRoomRules.translate("Shift+H: sort by rank or value; press again to reverse the order."),
            GameRoomRules.translate("Shift+M: restore the order in which cards were received."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:table, "C\u00EDl hry",
              "V Rummy sb\u00EDr\u00E1\u0161 karty do kombinac\u00ED a vykl\u00E1d\u00E1\u0161 je na st\u016Fl. Dal\u0161\u00ED karty m\u016F\u017Ee\u0161 p\u0159id\u00E1vat k tomu, co u\u017E je vylo\u017Een\u00E9. Zahran\u00E9 karty p\u0159in\u00E1\u0161ej\u00ED body a pr\u00E1zdn\u00E1 ruka vyhraje kolo. Sk\u00F3re z kol se s\u010D\u00EDt\u00E1; jakmile n\u011Bkdo dos\u00E1hne 1000, partii vyhraje hr\u00E1\u010D s nejvy\u0161\u0161\u00EDm v\u00FDsledkem.",
              "Hraj\u00ED dva a\u017E osm hr\u00E1\u010D\u016F. Na za\u010D\u00E1tku ka\u017Ed\u00E9ho kola dostane\u0161 \u010Dtrn\u00E1ct karet.",
              "Ruku proch\u00E1z\u00ED\u0161 \u0161ipkami. Shift+C ji se\u0159ad\u00ED podle barev, Shift+H podle hodnot; opakov\u00E1n\u00EDm po\u0159ad\u00ED obr\u00E1t\u00ED\u0161. P\u016Fvodn\u00ED po\u0159ad\u00ED p\u0159ijat\u00FDch karet vr\u00E1t\u00ED Shift+M."),
            rule_section(:combinations, "Postupky a skupiny",
              "Vykl\u00E1daj\u00ED se kombinace nejm\u00E9n\u011B t\u0159\u00ED karet. Z\u00E1kladn\u00ED jsou dv\u011B:",
              "- Postupka: sousedn\u00ED hodnoty stejn\u00E9 barvy, t\u0159eba srdcov\u00E1 5, 6 a 7. Pozd\u011Bji k n\u00ED pasuje srdcov\u00E1 4 z jedn\u00E9 strany nebo 8 z druh\u00E9.",
              "- Skupina: t\u0159i \u010Di \u010Dty\u0159i stejn\u00E9 hodnoty r\u016Fzn\u00FDch barev, t\u0159eba srdcov\u00E1, k\u00E1rov\u00E1 a pikov\u00E1 d\u00E1ma. Doplnit ji m\u016F\u017Ee je\u0161t\u011B k\u0159\u00ED\u017Eov\u00E1 d\u00E1ma.",
              "Eso m\u016F\u017Ee st\u00E1t p\u0159ed dvojkou nebo za kr\u00E1lem. Plat\u00ED tedy A, 2, 3 i d\u00E1ma, kr\u00E1l, eso; kr\u00E1l, eso, dvojka platn\u00E1 postupka nen\u00ED.",
              "\u017Dol\u00EDk nahrad\u00ED jednu chyb\u011Bj\u00EDc\u00ED kartu. V kombinaci sm\u00ED b\u00FDt jen jeden a mus\u00ED m\u00EDt nejm\u00E9n\u011B dv\u011B b\u011B\u017En\u00E9 karty. U postupky rozhoduje po\u0159ad\u00ED v\u00FDb\u011Bru: \u017Eol\u00EDk, pikov\u00E1 3, pikov\u00E1 4 za\u010D\u00EDn\u00E1 dvojkou, zat\u00EDmco pikov\u00E1 3, pikov\u00E1 4, \u017Eol\u00EDk kon\u010D\u00ED p\u011Btkou."),
            rule_section(:turn, "Od dobr\u00E1n\u00ED k odhozen\u00ED",
              "Tah za\u010Dni dobr\u00E1n\u00EDm jedn\u00E9 karty mezern\u00EDkem. Pokud u\u017E m\u00E1\u0161 za sebou prvn\u00ED vylo\u017Een\u00ED, m\u016F\u017Ee\u0161 m\u00EDsto bal\u00ED\u010Dku vz\u00EDt posledn\u00ED odhozenou kartu. D ji p\u0159e\u010Dte a Shift+D vezme.",
              "Po dobr\u00E1n\u00ED sm\u00ED\u0161 vykl\u00E1dat kombinace. S dokon\u010Den\u00FDm prvn\u00EDm vylo\u017Een\u00EDm tak\u00E9 p\u0159id\u00E1v\u00E1\u0161 k vlastn\u00EDm i ciz\u00EDm kombinac\u00EDm na stole, klidn\u011B n\u011Bkolikr\u00E1t za tah. Dobranou kartu nemus\u00ED\u0161 hned pou\u017E\u00EDt a sm\u00ED\u0161 se rozhodnout nevykl\u00E1dat nic.",
              "Na konci vyber jednu kartu a odho\u010F ji kl\u00E1vesou Delete. T\u00EDm p\u0159ed\u00E1\u0161 tah dal\u0161\u00EDmu hr\u00E1\u010Di.",
              "Vypr\u00E1zdn\u00ED\u0161-li ruku vylo\u017Een\u00EDm \u010Di p\u0159ilo\u017Een\u00EDm, kolo skon\u010D\u00ED rovnou. Posledn\u00ED kartu si na odhozen\u00ED schov\u00E1vat nemus\u00ED\u0161."),
            rule_section(:opening, "Prvn\u00ED vylo\u017Een\u00ED",
              "Poprv\u00E9 v ka\u017Ed\u00E9m kole mus\u00ED\u0161 najednou vylo\u017Eit alespo\u0148 30 bod\u016F. M\u016F\u017Ee to b\u00FDt jedna kombinace nebo v\u00EDce spole\u010Dn\u011B. Teprve potom sm\u00ED\u0161 p\u0159ikl\u00E1dat na st\u016Fl a od p\u0159\u00ED\u0161t\u00EDho tahu tak\u00E9 dob\u00EDrat odhozen\u00E9 karty.",
              "P\u0159\u00EDpravu nov\u00E9 kombinace za\u010Dne N. \u0160ipkami vyber prvn\u00ED kartu a Enterem ji ozna\u010D, potom stejn\u011B dal\u0161\u00ED. Postupku vyb\u00EDrej od nejni\u017E\u0161\u00ED po nejvy\u0161\u0161\u00ED: u 5, 6, 7 nejd\u0159\u00EDv p\u011Btku. Dal\u0161\u00ED Enter na ozna\u010Den\u00E9 kart\u011B ji z v\u00FDb\u011Bru odstran\u00ED.",
              "Pot\u0159ebuje\u0161-li k dosa\u017Een\u00ED minima v\u00EDc kombinac\u00ED, po ozna\u010Den\u00ED prvn\u00ED znovu stiskni N a p\u0159iprav druhou. Zat\u00EDm nic nevykl\u00E1d\u00E1\u0161. Kl\u00E1vesa P p\u0159e\u010Dte p\u0159ipraven\u00E9 kombinace i jejich sou\u010Det.",
              "V\u0161e vylo\u017E najednou kl\u00E1vesou F. Pokud n\u011Bco chyb\u00ED nebo kombinace neplat\u00ED, usly\u0161\u00ED\u0161 d\u016Fvod a m\u016F\u017Ee\u0161 v\u00FDb\u011Br upravit. Shift+P otev\u0159e p\u0159ipraven\u00E9 kombinace, Enter na vybran\u00E9 dovol\u00ED opravu \u010Di odstran\u011Bn\u00ED. Escape p\u0159i p\u0159\u00EDprav\u011B zru\u0161\u00ED cel\u00E9 p\u0159ipravovan\u00E9 vylo\u017Een\u00ED.",
              "Po prvn\u00EDm vylo\u017Een\u00ED u\u017E bodov\u00E9 minimum neplat\u00ED. Nov\u00E9 kombinace tvo\u0159\u00ED\u0161 stejn\u011B a je\u0161t\u011B v t\u00E9m\u017Ee tahu sm\u00ED\u0161 rovnou p\u0159ikl\u00E1dat ke stolu."),
            rule_section(:laying, "P\u0159ikl\u00E1d\u00E1n\u00ED na st\u016Fl",
              "Kl\u00E1vesa C otev\u0159e seznam vylo\u017Een\u00FDch kombinac\u00ED. Proch\u00E1zej je \u0161ipkami, Enter je p\u0159e\u010Dte a Escape vr\u00E1t\u00ED do ruky.",
              "Pro p\u0159ilo\u017Een\u00ED vyber kartu v ruce a stiskni Enter, ani\u017E bys p\u0159edt\u00EDm za\u010Dal p\u0159\u00EDpravu pomoc\u00ED N. Z nab\u00EDdky vhodn\u00FDch m\u00EDst vyber jedno a potvr\u010F Enterem.",
              "Z najde dal\u0161\u00ED kartu vhodnou k p\u0159ilo\u017Een\u00ED, Shift+Z p\u0159edchoz\u00ED. P\u0159i jedin\u00E9 vhodn\u00E9 kart\u011B ji zkratka m\u016F\u017Ee rovnou p\u0159ilo\u017Eit.",
              "Postupku prodlou\u017E\u00ED\u0161 na obou konc\u00EDch. Ke t\u0159em stejn\u00FDm hodnot\u00E1m lze p\u0159idat chyb\u011Bj\u00EDc\u00ED \u010Dtvrtou barvu. Samotn\u00FD \u017Eol\u00EDk kombinaci neprodlu\u017Euje: pat\u0159\u00ED do nov\u00E9 s alespo\u0148 dv\u011Bma b\u011B\u017En\u00FDmi kartami."),
            rule_section(:joker, "V\u00FDm\u011Bna \u017Eol\u00EDka",
              "Po prvn\u00EDm vylo\u017Een\u00ED sm\u00ED\u0161 z\u00EDskat \u017Eol\u00EDka ze stolu v\u00FDm\u011Bnou za kartu, kterou p\u0159edstavuje. Do postupky \u017Eol\u00EDk, pikov\u00E1 3, pikov\u00E1 4 tedy pot\u0159ebuje\u0161 pikovou dvojku. Vyber ji, stiskni Enter a u dan\u00E9 kombinace potvr\u010F nahrazen\u00ED \u017Eol\u00EDka. Dvojka z\u016Fstane na stole a \u017Eol\u00EDk p\u0159ijde do ruky.",
              "Ve skupin\u011B srdcov\u00E1 7, k\u00E1rov\u00E1 7 a \u017Eol\u00EDk jeho barva je\u0161t\u011B nen\u00ED ur\u010Dena: m\u016F\u017Ee b\u00FDt pikov\u00FD nebo k\u0159\u00ED\u017Eov\u00FD. Nejd\u0159\u00EDv mus\u00ED\u0161 jednu z t\u011Bchto sedmi\u010Dek p\u0159ilo\u017Eit. Po pikov\u00E9 u\u017E \u017Eol\u00EDk p\u0159edstavuje jen k\u0159\u00ED\u017Eovou a pr\u00E1v\u011B tou ho lze vym\u011Bnit.",
              "Nevylo\u017E\u00ED\u0161-li z\u00EDskan\u00E9ho \u017Eol\u00EDka do konce tahu v nov\u00E9 kombinaci, ztrat\u00ED\u0161 300 bod\u016F. Ani odhozen\u00ED p\u0159ed trestem neochr\u00E1n\u00ED. Trest p\u0159ijde jen jednou; v dal\u0161\u00EDch taz\u00EDch u\u017E je \u017Eol\u00EDk b\u011B\u017Enou sou\u010D\u00E1st\u00ED ruky."),
            rule_section(:values, "Hodnoty karet",
              "Pro prvn\u00ED vylo\u017Een\u00ED i body za hran\u00E9 karty plat\u00ED:",
              "- Dvojky a\u017E dev\u00EDtky po 5 bodech.",
              "- Des\u00EDtka, kluk, d\u00E1ma a kr\u00E1l po 10.",
              "- Eso za 15, ale na za\u010D\u00E1tku postupky p\u0159ed dvojkou za 5.",
              "Vylo\u017Een\u00FD \u017Eol\u00EDk m\u00E1 hodnotu zastupovan\u00E9 karty. V postupce 3, 4, \u017Eol\u00EDk zastoup\u00ED p\u011Btku a kombinace d\u00E1v\u00E1 15 bod\u016F. Ve zb\u00FDvaj\u00EDc\u00ED ruce je \u017Eol\u00EDk za 20 a eso za 15."),
            rule_section(:normal, "Bodov\u00E1n\u00ED a v\u00EDt\u011Bzstv\u00ED",
              "Body z\u00EDsk\u00E1v\u00E1\u0161 za ka\u017Edou vylo\u017Eenou i p\u0159ilo\u017Eenou kartu. Pr\u00E1zdn\u00E1 ruka ukon\u010D\u00ED kolo. Ostatn\u00EDm dosavadn\u00ED body z\u016Fstanou a v\u00EDt\u011Bz nav\u00EDc z\u00EDsk\u00E1 sou\u010Det hodnot v\u0161ech jejich zb\u00FDvaj\u00EDc\u00EDch karet.",
              "Za dokon\u010Den\u00ED kola lze dostat pr\u00E9mie:",
              "- Rummy d\u00E1v\u00E1 200 bod\u016F, pokud prvn\u00ED vylo\u017Een\u00ED i zbaven\u00ED se posledn\u00ED karty prob\u011Bhly ve stejn\u00E9m tahu.",
              "- \u010Cist\u00E9 rummy d\u00E1v\u00E1 m\u00EDsto toho 300. Mus\u00ED\u0161 takto skon\u010Dit jen z vlastn\u00ED ruky, bez p\u0159ikl\u00E1d\u00E1n\u00ED ke star\u0161\u00EDm kombinac\u00EDm a bez v\u00FDm\u011Bny \u017Eol\u00EDk\u016F.",
              "- Dal\u0161\u00EDch 100 dostane\u0161 za konec kola d\u0159\u00EDv, ne\u017E kdokoli ze soupe\u0159\u016F poprv\u00E9 vylo\u017E\u00ED. Tato pr\u00E9mie plat\u00ED i bez rummy.",
              "Po kole, v n\u011Bm\u017E n\u011Bkdo dos\u00E1hne 1000, vyhraje nejvy\u0161\u0161\u00ED sk\u00F3re. P\u0159i shod\u011B na prvn\u00EDm m\u00EDst\u011B se hraje dal\u0161\u00ED kolo.",
              "Sk\u00F3re p\u0159e\u010Dte S, po\u010Dty karet hr\u00E1\u010D\u016F a dob\u00EDrac\u00ED z\u00E1soby E, hr\u00E1\u010De na tahu T."),
            rule_section(:blocked, "Pr\u00E1zdn\u00FD dob\u00EDrac\u00ED bal\u00ED\u010Dek",
              "Kdy\u017E bal\u00ED\u010Dek dojde, odhozen\u00E9 karty se zam\u00EDchaj\u00ED k nov\u00E9mu dob\u00EDr\u00E1n\u00ED. Posledn\u00ED odhozen\u00E1 z\u016Fstane dostupn\u00E1 pomoc\u00ED Shift+D. Nen\u00ED-li u\u017E odkud vz\u00EDt kartu, sm\u00ED\u0161 vykl\u00E1dat a p\u0159ikl\u00E1dat bez dobr\u00E1n\u00ED.",
              "Pokud nen\u00ED odkud dob\u00EDrat a dv\u011B cel\u00E1 kola tah\u016F nikdo nevylo\u017E\u00ED ani nep\u0159ilo\u017E\u00ED kartu z ruky, kolo skon\u010D\u00ED. Ka\u017Ed\u00FD si ponech\u00E1 body za sv\u00E9 vylo\u017Een\u00ED, ale nen\u00ED v\u00EDt\u011Bz kola ani z\u00E1v\u011Bre\u010Dn\u00E9 pr\u00E9mie."),
            rule_section(:variants, "Voliteln\u00E9 varianty",
              "P\u0159i zakl\u00E1d\u00E1n\u00ED stolu lze zvolit n\u00E1sleduj\u00EDc\u00ED zm\u011Bny. Co varianta nem\u011Bn\u00ED, plat\u00ED jako v z\u00E1kladn\u00ED h\u0159e."),
            rule_section(:limits, "Prvn\u00ED vylo\u017Een\u00ED a bodov\u00FD c\u00EDl",
              "Prvn\u00ED vylo\u017Een\u00ED m\u016F\u017Ee m\u00EDt jin\u00E9 minimum ne\u017E 30. Ne\u017E za\u010Dne\u0161 p\u0159ikl\u00E1dat na st\u016Fl a dob\u00EDrat odhozen\u00E9 karty, mus\u00ED\u0161 vylo\u017Een\u00FDmi kombinacemi t\u00E9to hranice dos\u00E1hnout.",
              "Tak\u00E9 celkov\u00FD c\u00EDl lze zm\u011Bnit z 1000. V\u00EDt\u011Bz se po\u0159\u00E1d ur\u010Duje a\u017E po dokon\u010Den\u00ED kola."),
            rule_section(:discard, "Dal\u0161\u00ED pravidla odhazov\u00E1n\u00ED",
              "M\u00EDsto b\u011B\u017En\u00E9ho bran\u00ED posledn\u00ED odhozen\u00E9 karty lze zvolit:",
              "- Bran\u00ED i star\u0161\u00EDch odhozen\u00FDch karet. D p\u0159e\u010Dte v\u0161echny, Shift+D otev\u0159e seznam od nejnov\u011Bj\u0161\u00ED. Vyber \u0161ipkami a potvr\u010F Enterem: z\u00EDsk\u00E1\u0161 vybranou i v\u0161echny nov\u011Bj\u0161\u00ED nad n\u00ED. T\u0159et\u00ED polo\u017Eka tedy vezme t\u0159et\u00ED, druhou a prvn\u00ED kartu. Jedinou dostupnou vezme Shift+D rovnou.",
              "- Z\u00E1kaz dob\u00EDr\u00E1n\u00ED odhozen\u00FDch karet. Dob\u00EDr\u00E1\u0161 mezern\u00EDkem, tah nad\u00E1le kon\u010D\u00ED odhozen\u00EDm pomoc\u00ED Delete.",
              "- Hru bez odhazov\u00E1n\u00ED. Po dobr\u00E1n\u00ED a hran\u00ED ukon\u010D\u00ED\u0161 tah pomoc\u00ED Shift+F. Nevylo\u017Een\u00E9 karty z\u016Fstanou v ruce."),
            rule_section(:identities, "Kombinace toto\u017En\u00FDch karet",
              "Tato volba povol\u00ED t\u0159i \u010Di \u010Dty\u0159i \u00FApln\u011B stejn\u00E9 karty, nap\u0159\u00EDklad t\u0159i k\u0159\u00ED\u017Eov\u00E9 dev\u00EDtky. Ka\u017Ed\u00E1 v takov\u00E9 kombinaci m\u00E1 o 10 bod\u016F v\u00EDce ne\u017E b\u011B\u017En\u011B. Zv\u00FD\u0161en\u00ED plat\u00ED i pro minimum prvn\u00EDho vylo\u017Een\u00ED."),
            rule_section(:rounding, "P\u0159esn\u00E9 hodnoty bez zaokrouhlen\u00ED",
              "Vypnut\u00EDm zaokrouhlov\u00E1n\u00ED se hodnoty zm\u011Bn\u00ED:",
              "- Dvojky a\u017E dev\u00EDtky d\u00E1vaj\u00ED sv\u00E9 \u010D\u00EDslo m\u00EDsto p\u011Bti bod\u016F.",
              "- Eso p\u0159ed dvojkou d\u00E1v\u00E1 1, v ostatn\u00EDch kombinac\u00EDch a v ruce 11.",
              "- Des\u00EDtky a figury z\u016Fst\u00E1vaj\u00ED po 10.",
              "- \u017Dol\u00EDk v ruce z\u016Fst\u00E1v\u00E1 za 20."),
            rule_section(:manipulation, "P\u0159estavov\u00E1n\u00ED kombinac\u00ED",
              "S povolen\u00FDm p\u0159estavov\u00E1n\u00EDm sm\u00ED\u0161 m\u011Bnit kombinace na stole. Nejprve mus\u00ED\u0161 m\u00EDt spln\u011Bn\u00E9 prvn\u00ED vylo\u017Een\u00ED a v tomto tahu dobrat. Pomoc\u00ED C otev\u0159i st\u016Fl, vyber kombinaci a stiskni kl\u00E1vesu m\u00EDstn\u00ED nab\u00EDdky. Nab\u00EDz\u00ED spojov\u00E1n\u00ED i odebr\u00E1n\u00ED cel\u00E9 kombinace nebo jednotliv\u00FDch karet.",
              "Odebran\u00E9 karty m\u016F\u017Ee\u0161 pou\u017E\u00EDt jinde. Co sm\u00ED\u0161 vz\u00EDt, z\u00E1vis\u00ED na kombinaci:",
              "- Z postupky prvn\u00ED nebo posledn\u00ED kartu, pokud z\u016Fstanou alespo\u0148 t\u0159i sousedn\u00ED. Ze srdcov\u00FDch 4, 5, 6, 7 tedy \u010Dty\u0159ku nebo sedmi\u010Dku.",
              "- Ze skupiny \u010Dty\u0159 stejn\u00FDch hodnot jednu kartu.",
              "- Celou kombinaci jen bez \u017Eol\u00EDka. \u017Dol\u00EDka mus\u00ED\u0161 nejprve z\u00EDskat v\u00FDm\u011Bnou za spr\u00E1vnou kartu.",
              "Odeb\u00EDr\u00E1n\u00ED ostatn\u00EDch karet nesm\u00ED zm\u011Bnit v\u00FDznam zb\u00FDvaj\u00EDc\u00EDho \u017Eol\u00EDka.",
              "Pro spojen\u00ED zvol v nab\u00EDdce spojov\u00E1n\u00ED a pak druhou kombinaci. Dohromady mus\u00ED b\u00FDt platn\u00E9: srdcov\u00E9 4, 5, 6 a 7, 8, 9 spojit lze, dv\u011B postupky s chyb\u011Bj\u00EDc\u00ED kartou mezi nimi ne.",
              "Za ka\u017Edou odebranou kartu, kterou do konce tahu znovu nevyu\u017Eije\u0161, dostane\u0161 trest 300 bod\u016F. Stejn\u011B se posuzuje z\u00EDskan\u00FD \u017Eol\u00EDk. Dv\u011B nevyu\u017Eit\u00E9 karty tedy stoj\u00ED 600. Mohou z\u016Fstat v ruce a po trestu se chovaj\u00ED b\u011B\u017En\u011B; odhozen\u00ED ale nov\u00E9 vylo\u017Een\u00ED nenahrazuje.",
              "Odebr\u00E1n\u00EDm ze stolu ztrat\u00ED\u0161 bodovou hodnotu karet, op\u011Btovn\u00FDm vylo\u017Een\u00EDm ji z\u00EDsk\u00E1\u0161 zp\u011Bt. Samotn\u00E9 spojen\u00ED nic neboduje. Odebr\u00E1n\u00ED by\u0165 jedin\u00E9 karty vylou\u010D\u00ED \u010Dist\u00E9 rummy."),
            rule_section(:elimination, "Vy\u0159azovac\u00ED re\u017Eim",
              "Zde chce\u0161 co nejm\u00E9n\u011B bod\u016F. Vylo\u017Een\u00ED, p\u0159ilo\u017Een\u00ED a odebr\u00E1n\u00ED ze stolu sk\u00F3re nem\u011Bn\u00ED, minimum prvn\u00EDho vylo\u017Een\u00ED ale plat\u00ED. V\u00EDt\u011Bz kola nedost\u00E1v\u00E1 body za karty, ostatn\u00ED si p\u0159i\u010Dtou hodnotu sv\u00E9 ruky. Tresty se p\u0159i\u010D\u00EDtaj\u00ED m\u00EDsto ode\u010D\u00EDt\u00E1n\u00ED.",
              "Pr\u00E9mie za rummy nahrad\u00ED n\u00E1soben\u00ED soupe\u0159ov\u00FDch zb\u00FDvaj\u00EDc\u00EDch karet:",
              "- P\u0159i rummy je soupe\u0159i po\u010D\u00EDtaj\u00ED dvakr\u00E1t.",
              "- P\u0159i \u010Dist\u00E9m rummy t\u0159ikr\u00E1t.",
              "- P\u0159i \u010Dist\u00E9m rummy d\u0159\u00EDv, ne\u017E kdokoli jin\u00FD poprv\u00E9 vylo\u017E\u00ED, \u010Dty\u0159ikr\u00E1t.",
              "Tyto n\u00E1sobi\u010De nezvy\u0161uj\u00ED tresty.",
              "P\u0159i zablokovan\u00E9m kole si zb\u00FDvaj\u00EDc\u00ED ruku zapo\u010D\u00EDtaj\u00ED v\u0161ichni.",
              "Po kole vypadnou ti, kdo dos\u00E1hli limitu, v\u00FDchoz\u00EDho 500 bod\u016F. Posledn\u00ED hr\u00E1\u010D vyhraje. Dos\u00E1hnou-li limitu v\u0161ichni sou\u010Dasn\u011B, v\u00EDt\u011Bz\u00ED nejni\u017E\u0161\u00ED sk\u00F3re; p\u0159i shod\u011B je v\u00EDt\u011Bzstv\u00ED spole\u010Dn\u00E9."),
            rule_section(:time, "\u010Cas a soub\u011B\u017En\u00E9 tresty",
              "Se zapnut\u00FDm \u010Dasov\u00FDm limitem mus\u00ED\u0161 tah v\u010Das dokon\u010Dit. P\u0159ekro\u010Den\u00ED stoj\u00ED 50 bod\u016F a p\u0159ed\u00E1 \u0159adu d\u00E1l. Pokud jsi je\u0161t\u011B nedobral, dostane\u0161 nav\u00EDc jednu kartu z bal\u00ED\u010Dku, je-li dostupn\u00E1. U\u017E prob\u011Bhl\u00E9 dobr\u00E1n\u00ED se neopakuje. Za vypr\u0161en\u00ED \u010Dasu se karta neodhazuje.",
              "Tresty se s\u010D\u00EDtaj\u00ED. Vypr\u0161en\u00ED \u010Dasu s jedn\u00EDm nevyu\u017Eit\u00FDm \u017Eol\u00EDkem ze stolu znamen\u00E1 350 bod\u016F. V z\u00E1kladn\u00ED h\u0159e se ode\u010Dtou, ve vy\u0159azovac\u00ED p\u0159i\u010Dtou."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipky: proch\u00E1zet ruku nebo otev\u0159en\u00FD seznam.",
              "Mezern\u00EDk: dobrat z bal\u00ED\u010Dku.",
              "D: p\u0159e\u010D\u00EDst dostupn\u00E9 odhozen\u00E9 karty.",
              "Shift+D: vz\u00EDt odhozenou kartu nebo otev\u0159\u00EDt jejich v\u00FDb\u011Br.",
              "N: za\u010D\u00EDt p\u0159\u00EDpravu kombinace; opakov\u00E1n\u00EDm p\u0159ipravit dal\u0161\u00ED do stejn\u00E9ho vylo\u017Een\u00ED.",
              "Enter p\u0159i p\u0159\u00EDprav\u011B: ozna\u010Dit \u010Di odzna\u010Dit kartu.",
              "P: p\u0159e\u010D\u00EDst p\u0159ipraven\u00E9 kombinace a hodnotu.",
              "Shift+P: vybrat p\u0159ipravenou kombinaci k oprav\u011B \u010Di odstran\u011Bn\u00ED.",
              "F: vylo\u017Eit p\u0159ipraven\u00E9 kombinace.",
              "Escape: zav\u0159\u00EDt seznam nebo zru\u0161it p\u0159\u00EDpravu vylo\u017Een\u00ED.",
              "Enter na kart\u011B mimo p\u0159\u00EDpravu: vybrat p\u0159ilo\u017Een\u00ED \u010Di v\u00FDm\u011Bnu \u017Eol\u00EDka; nehod\u00EDc\u00ED se kartu lze odhodit.",
              "Delete: odhodit kartu a ukon\u010Dit tah.",
              "Shift+F: ukon\u010Dit tah p\u0159i h\u0159e bez odhazov\u00E1n\u00ED.",
              "C: otev\u0159\u00EDt kombinace na stole.",
              "E: p\u0159e\u010D\u00EDst po\u010Dty karet hr\u00E1\u010D\u016F a dob\u00EDrac\u00ED z\u00E1soby.",
              "S: p\u0159e\u010D\u00EDst sk\u00F3re.",
              "T: ozn\u00E1mit, kdo je na tahu.",
              "Kl\u00E1vesa m\u00EDstn\u00ED nab\u00EDdky v seznamu kombinac\u00ED: vybrat odeb\u00EDr\u00E1n\u00ED \u010Di spojov\u00E1n\u00ED p\u0159i zapnut\u00E9 variant\u011B.",
              "Z: naj\u00EDt dal\u0161\u00ED vhodnou kartu; p\u0159i jedin\u00E9 mo\u017Enosti ji m\u016F\u017Ee rovnou p\u0159ilo\u017Eit.",
              "Shift+Z: naj\u00EDt p\u0159edchoz\u00ED vhodnou kartu; p\u0159i jedin\u00E9 mo\u017Enosti ji m\u016F\u017Ee rovnou p\u0159ilo\u017Eit.",
              "Shift+C: se\u0159adit podle barev; opakov\u00E1n\u00EDm obr\u00E1tit po\u0159ad\u00ED.",
              "Shift+H: se\u0159adit podle hodnot; opakov\u00E1n\u00EDm obr\u00E1tit po\u0159ad\u00ED.",
              "Shift+M: obnovit po\u0159ad\u00ED p\u0159ijat\u00FDch karet.")
          ]
        when "en"
          [
            rule_section(:table, "Aim of the game",
              "In Rummy, you collect cards that go together and lay them on the table. You can also add cards to combinations already in play. Each card you play earns points, and emptying your hand wins the round. Scores carry over between rounds. At the end of a round, if anyone has at least 1,000 points, the highest score wins.",
              "Two to eight people can play. Each round begins with fourteen cards in your hand.",
              "Use the arrow keys to browse your hand. Shift+C sorts it by suit and Shift+H by rank; press either shortcut again to reverse that order. Shift+M restores the order in which you received the cards."),
            rule_section(:combinations, "Runs and sets",
              "A combination must contain at least three cards. There are two kinds:",
              "- A run consists of consecutive cards in one suit, such as the 5, 6 and 7 of hearts. You could later extend it with the 4 or 8 of hearts.",
              "- A set consists of three or four cards of the same rank in different suits. For example, the queens of hearts, diamonds and spades form a set, to which you can add the queen of clubs.",
              "An ace can come before a two or after a king. Ace\u20132\u20133 and queen\u2013king\u2013ace are valid runs; king\u2013ace\u20132 is not.",
              "A joker stands for one missing card. Each combination may contain one joker and must have at least two ordinary cards. In a run, the order in which you select the cards determines what the joker represents. Joker, 3 of spades, 4 of spades starts at two; 3 of spades, 4 of spades, joker ends at five."),
            rule_section(:turn, "Your turn",
              "Start by pressing Space to draw one card. Once you have made your opening meld, you may instead take the last card another player discarded. Press D to hear that card or Shift+D to take it.",
              "After drawing, you can lay down combinations. Once you have made your opening meld, you can also add to anyone's combinations on the table. You may make several plays in a turn, or keep your cards and wait. You do not have to use the card you just drew.",
              "To end your turn, select a card and press Delete to discard it. Play then passes to the next person.",
              "If laying down or adding cards empties your hand, the round ends immediately. You do not need to keep a card for a final discard."),
            rule_section(:opening, "Your opening meld",
              "The first cards you lay down in each round must be worth at least 30 points. This opening meld can contain one combination or several laid down together. It lets you add cards to combinations on the table, and from your next turn onwards, draw discarded cards.",
              "Press N to prepare a combination. Find each card with the arrow keys and select it with Enter. Select a run from lowest to highest: for 5\u20136\u20137, choose the five first, then the six and seven. Pressing Enter on a selected card removes it from your selection.",
              "If you need another combination to reach 30 points, press N again and select its cards. Nothing has been played yet. Press P to hear your prepared combinations and their total value.",
              "Press F to lay down all the prepared combinations together. If one is invalid or you have not reached the opening value, the game explains why so you can change your selection. Shift+P opens your prepared combinations; select one and press Enter to edit or remove it. Escape cancels the entire prepared meld.",
              "After your opening meld, there is no minimum point value for new combinations. Prepare and play them with the same keys. You can also add to combinations already on the table, including during the turn in which you opened."),
            rule_section(:laying, "Adding cards",
              "Press C to browse the combinations on the table. Use the arrow keys, press Enter to hear the selected combination, and Escape to return to your hand.",
              "To add a card, select it in your hand and press Enter without first pressing N. Choose one of the places where it fits and confirm with Enter.",
              "Z finds the next card that can be added, and Shift+Z finds the previous one. If there is only one suitable card, the shortcut may play it straight away.",
              "You can extend a run at either end, or add the missing suit to a three-card set. You cannot extend a combination with a joker alone: play the joker in a new combination with at least two ordinary cards."),
            rule_section(:joker, "Taking back a joker",
              "After your opening meld, you can take a joker from the table by replacing it with the card it represents. For a run of joker, 3 of spades, 4 of spades, you need the 2 of spades. Select that card, press Enter and choose the joker replacement for that combination. Your two stays on the table and the joker joins your hand.",
              "A set containing the 7 of hearts, 7 of diamonds and a joker leaves two possibilities: the joker could be the 7 of spades or the 7 of clubs. First add one of those cards. If you add the 7 of spades, the joker now represents the 7 of clubs, and that is the card you need to replace it.",
              "You must use the recovered joker in a new combination before your turn ends. Otherwise, you lose 300 points, even if you discarded it. This penalty is charged only once; on later turns, you can use the joker like any other card in your hand."),
            rule_section(:values, "Card values",
              "These values apply both to your opening meld and to points earned by playing cards:",
              "- Cards from two to nine are worth 5 points each.",
              "- Tens, jacks, queens and kings are worth 10 points each.",
              "- An ace is worth 15 points, or 5 when it starts a run before a two.",
              "A played joker is worth as much as the card it represents. In 3\u20134\u2013joker, it stands for a five, so the run is worth 15 points. When counting cards left in a hand, a joker is worth 20 points and an ace 15."),
            rule_section(:normal, "Scoring and winning",
              "You earn points for each card you lay down or add to a combination. When someone empties their hand, everyone keeps the points they have earned. The round winner also receives the combined value of all cards left in the other players' hands.",
              "You can earn these bonuses for finishing a round:",
              "- Rummy: 200 points for making your opening meld and emptying your hand in the same turn.",
              "- Pure rummy: 300 points instead of 200 if you finish with rummy using only cards from your own hand, without adding to existing combinations or recovering jokers.",
              "- An extra 100 points for finishing before any opponent has made an opening meld. You can earn this even without finishing with rummy.",
              "Once someone reaches 1,000 points, finish the round and compare the scores. The highest score wins. If the lead is tied, play another round.",
              "S reads the scores. E gives the number of cards in each hand and the number available to draw. T tells you whose turn it is."),
            rule_section(:blocked, "When the draw pile runs out",
              "Discarded cards are shuffled to make a new draw pile. The latest discard remains available through Shift+D. If there is nowhere left to draw from, you can lay down and add cards without drawing.",
              "If nobody lays down or adds a card from their hand for two complete rounds of turns while no cards are available to draw, the round ends. Everyone keeps their points from playing cards, but there is no round winner or finishing bonus."),
            rule_section(:variants, "Variants",
              "The table settings let you change the following rules. Everything else is played as described above."),
            rule_section(:limits, "Opening value and score limit",
              "You can set an opening value other than 30. You must lay down combinations worth at least that amount before you can add to existing combinations or draw discarded cards.",
              "You can also replace the 1,000-point score limit. Reaching the chosen limit still ends the game only after the round has been scored."),
            rule_section(:discard, "Drawing and discarding options",
              "Instead of allowing players to draw only the latest discard, you can choose one of these rules:",
              "- Allow earlier discards. D reads all available discards, and Shift+D opens a list with the newest first. Choose a card and press Enter to take it and every card discarded after it. Choosing the third card therefore gives you cards three, two and one. If only one card is available, Shift+D takes it immediately.",
              "- Do not allow drawing discards. Draw with Space and still discard with Delete at the end of your turn.",
              "- Do not discard cards. After drawing and making your plays, press Shift+F to end your turn. All unplayed cards stay in your hand."),
            rule_section(:identities, "Identical-card combinations",
              "This option allows a combination of three or four identical cards, such as three nines of clubs. Each card in such a combination is worth 10 points more than usual. The extra points also count towards your opening meld."),
            rule_section(:rounding, "Unrounded scoring",
              "Turning off rounded scoring changes these card values:",
              "- Cards from two to nine are worth their printed number rather than 5 points.",
              "- An ace before a two is worth 1 point. In other combinations, or left in your hand, it is worth 11.",
              "- Tens and face cards are still worth 10 points.",
              "- A joker left in your hand is worth 20 points."),
            rule_section(:manipulation, "Rearranging combinations",
              "With manipulation enabled, you can take cards from the table and rearrange its combinations. You must have made your opening meld and drawn for the current turn. Press C, choose a combination and open its context menu. The menu lets you merge combinations or take whole combinations or individual cards.",
              "The cards you can take depend on the combination:",
              "- From a run, you may take an end card if at least three consecutive cards remain. For example, from 4\u20135\u20136\u20137 of hearts you may take the four or the seven.",
              "- From a four-card set, you may take one card.",
              "- You may take an entire combination only if it contains no joker. To take one with a joker, first recover the joker by replacing it with the correct card.",
              "Taking other cards must not change which card a joker represents.",
              "To join combinations, choose Merge and then the other combination. Together they must form a valid whole. Runs of 4\u20135\u20136 and 7\u20138\u20139 of hearts can be merged; runs separated by a missing card cannot.",
              "Each card taken from the table and not played again by the end of your turn costs you 300 points. This also applies to a recovered joker, so two unused cards cost 600 points. They can stay in your hand and, after the penalty, be used normally on later turns. Discarding a taken card does not count as playing it again.",
              "Taking cards from the table removes their value from your score. Playing them again earns those points back. Merging combinations earns no points. Taking even one card from the table prevents you from finishing with pure rummy."),
            rule_section(:elimination, "Elimination mode",
              "In this mode, aim for the lowest score. Playing cards or taking them from the table does not change your score, but you still need to meet the opening value. The round winner scores no points for cards; everyone else adds the value of the cards left in their hand. Penalties are added rather than subtracted.",
              "Instead of earning rummy bonuses, you increase the other players' points for their remaining cards:",
              "- Finish with rummy, and they count those cards twice.",
              "- Finish with pure rummy, and they count them three times.",
              "- Finish with pure rummy before anyone else has opened, and they count them four times.",
              "These multipliers do not increase penalties.",
              "If a round is blocked, everyone adds the value of the cards left in their hand.",
              "Players who reach the score limit, 500 by default, are eliminated after the round. The last player remaining wins. If everyone reaches the limit in the same round, the lowest score wins; a tie for lowest score is a shared win."),
            rule_section(:time, "Time limit and penalties",
              "If a turn time limit is enabled, you must finish your turn before it expires. Running out of time costs 50 points and passes the turn to the next player. If you have not drawn yet, you also receive one card from the draw pile if one is available. You do not draw a second card if you have already drawn. Running out of time does not make you discard a card.",
              "Penalties add up. Running out of time with one unused joker recovered from the table costs 350 points in total. Penalties are subtracted in normal play and added in elimination mode."),
            rule_section(:controls, "Keyboard shortcuts",
              "Arrow keys: browse your hand or an open list.",
              "Space: draw from the draw pile.",
              "D: read the available discards.",
              "Shift+D: take the discard or open the discard list.",
              "N: prepare a combination; press again to start another combination in the same meld.",
              "Enter while preparing a combination: select or deselect a card.",
              "P: read your prepared combinations and their value.",
              "Shift+P: choose a prepared combination to edit or remove.",
              "F: lay down your prepared combinations.",
              "Escape: close a list or cancel the prepared meld.",
              "Enter on a card when not preparing a combination: choose where to add it or replace a joker; if it fits nowhere, you can discard it.",
              "Delete: discard the selected card and end your turn.",
              "Shift+F: end your turn when discarding is disabled.",
              "C: open the combinations on the table.",
              "E: read card counts.",
              "S: read the scores.",
              "T: announce whose turn it is.",
              "Context menu key on a table combination: take cards or merge combinations when manipulation is enabled.",
              "Z: find the next card you can add; may play it immediately if there is only one.",
              "Shift+Z: find the previous card you can add; may play it immediately if there is only one.",
              "Shift+C: sort by suit; press again to reverse.",
              "Shift+H: sort by rank; press again to reverse.",
              "Shift+M: restore the order in which you received the cards.")
          ]
        when "es"
          [
            rule_section(:table, "Objetivo",
              "En Rummy re\u00FAnes cartas para formar combinaciones y bajarlas a la mesa. Tambi\u00E9n puedes a\u00F1adir cartas a las combinaciones ya jugadas. Cada carta que juegas da puntos; quedarte sin cartas gana la ronda. Los resultados se acumulan y, cuando alguien llega a 1000, gana la partida quien tenga m\u00E1s puntos.",
              "Juegan de dos a ocho personas. Cada ronda empieza con catorce cartas por jugador.",
              "Recorre la mano con las flechas. Shift+C ordena por palos y Shift+H por valores; repetir cualquiera invierte el orden. Shift+M recupera el orden en que recibiste las cartas."),
            rule_section(:combinations, "Combinaciones v\u00E1lidas",
              "Una combinaci\u00F3n necesita al menos tres cartas. Hay dos tipos:",
              "- Escalera: valores consecutivos del mismo palo, como 5, 6 y 7 de corazones. Despu\u00E9s admite el 4 de corazones por un extremo o el 8 por el otro.",
              "- Grupo: tres o cuatro cartas del mismo valor y palos distintos, como reina de corazones, de diamantes y de picas. A ese grupo se le puede a\u00F1adir la reina de tr\u00E9boles.",
              "El as puede ir antes del dos o despu\u00E9s del rey. Son v\u00E1lidas as, 2, 3 y reina, rey, as; no lo es rey, as, 2.",
              "El comod\u00EDn sustituye una carta que falte. Cada combinaci\u00F3n admite solo uno y debe incluir al menos dos cartas normales. En una escalera, el orden de selecci\u00F3n fija su valor: comod\u00EDn, 3 de picas, 4 de picas empieza en el dos; 3 de picas, 4 de picas, comod\u00EDn termina en el cinco."),
            rule_section(:turn, "Un turno completo",
              "Empieza robando una carta con Espacio. Si ya has hecho tu primera bajada, puedes tomar en su lugar el \u00FAltimo descarte de otro jugador: D lo lee y Shift+D lo recoge.",
              "Despu\u00E9s puedes bajar combinaciones. Si ya has hecho la primera bajada, tambi\u00E9n puedes a\u00F1adir cartas a las tuyas o a las de otros. Puedes hacer varias jugadas en el mismo turno, pero no est\u00E1s obligado a usar la carta robada ni a bajar nada.",
              "Para terminar, selecciona una carta y desc\u00E1rtala con Supr. Pasa el turno al siguiente jugador.",
              "Si te quedas sin cartas al bajar una combinaci\u00F3n o a\u00F1adir cartas a otra, la ronda acaba al instante. No tienes que reservar una carta para descartarla."),
            rule_section(:opening, "La primera bajada",
              "Tu primera bajada de cada ronda debe valer al menos 30 puntos. Puedes reunirlos con una combinaci\u00F3n o varias presentadas juntas. A partir de esa bajada puedes a\u00F1adir cartas a la mesa; desde tu turno siguiente tambi\u00E9n puedes tomar descartes.",
              "Pulsa N para preparar una combinaci\u00F3n. Busca cada carta con las flechas y m\u00E1rcala con Enter. En una escalera, selecci\u00F3nalas de menor a mayor: para 5, 6, 7, marca primero el cinco, luego el seis y el siete. Enter sobre una carta ya marcada la retira de la preparaci\u00F3n.",
              "Si necesitas varias combinaciones para llegar al m\u00EDnimo, termina de marcar una, pulsa N otra vez y prepara la siguiente. A\u00FAn no has bajado nada. P lee todas las combinaciones preparadas y su valor para comprobar el total.",
              "Pulsa F para bajarlas juntas. Si falta algo o una combinaci\u00F3n no es v\u00E1lida, oir\u00E1s el motivo y podr\u00E1s corregirla. Shift+P abre la lista de combinaciones preparadas; Enter sobre una permite editarla o quitarla. Escape durante la preparaci\u00F3n cancela toda la bajada.",
              "Una vez abierta tu mano con esa primera bajada, ya no hay m\u00EDnimo de puntos para las siguientes. Se preparan con las mismas teclas. Tambi\u00E9n puedes empezar a a\u00F1adir cartas a la mesa en ese mismo turno."),
            rule_section(:laying, "A\u00F1adir cartas a la mesa",
              "C abre las combinaciones de la mesa. Rec\u00F3rrelas con las flechas, escucha una con Enter y vuelve a tu mano con Escape.",
              "Para a\u00F1adir una carta, selecci\u00F3nala en la mano y pulsa Enter sin haber iniciado una combinaci\u00F3n con N. Aparecer\u00E1n los lugares en que encaja; elige uno y confirma con Enter.",
              "Z busca la siguiente carta que puedes a\u00F1adir y Shift+Z la anterior. Si solo hay una posibilidad, el atajo puede a\u00F1adirla directamente.",
              "Las escaleras se ampl\u00EDan por cualquiera de sus extremos. Un grupo de tres admite el cuarto palo que le falta. Un comod\u00EDn solo no sirve para ampliar: debes bajarlo en una combinaci\u00F3n nueva con al menos dos cartas normales."),
            rule_section(:joker, "Recuperar un comod\u00EDn",
              "Despu\u00E9s de tu primera bajada puedes sustituir un comod\u00EDn de la mesa por la carta exacta que representa. En comod\u00EDn, 3 de picas, 4 de picas necesitas el 2 de picas. Selecci\u00F3nalo en tu mano, pulsa Enter y confirma la sustituci\u00F3n del comod\u00EDn en esa combinaci\u00F3n. El dos queda en la mesa y recibes el comod\u00EDn.",
              "En 7 de corazones, 7 de diamantes y comod\u00EDn a\u00FAn no se sabe si falta picas o tr\u00E9boles. Para recuperarlo debes a\u00F1adir primero una de esas cartas. Si a\u00F1ades el 7 de picas, el comod\u00EDn solo puede representar el 7 de tr\u00E9boles, y esa ser\u00E1 la carta necesaria para sustituirlo.",
              "Debes usar el comod\u00EDn recuperado en una combinaci\u00F3n nueva antes de terminar el turno. Si no lo haces, pierdes 300 puntos, incluso si lo descartas. La penalizaci\u00F3n se aplica una sola vez; en los turnos siguientes el comod\u00EDn se trata como cualquier otra carta de tu mano."),
            rule_section(:values, "Valor de las cartas",
              "Tanto para la primera bajada como para puntuar las cartas jugadas se usan estos valores:",
              "- Del dos al nueve: 5 puntos por carta.",
              "- Diez, jota, reina y rey: 10 puntos cada uno.",
              "- As: 15, salvo si inicia una escalera antes del dos, donde vale 5.",
              "Un comod\u00EDn jugado vale lo que representa. En 3, 4, comod\u00EDn, representa un cinco y la escalera vale 15 en total. Al contar las cartas que quedan en la mano, el comod\u00EDn vale 20 y el as 15."),
            rule_section(:normal, "Puntos y final de partida",
              "Ganas puntos por cada carta que bajes o a\u00F1adas. Cuando alguien vac\u00EDa su mano, termina la ronda. Los dem\u00E1s conservan sus puntos; el ganador recibe adem\u00E1s el valor de todas las cartas que les queden en las manos.",
              "Hay bonificaciones por cerrar la ronda:",
              "- Rummy: 200 puntos si haces tu primera bajada y te quedas sin cartas en el mismo turno.",
              "- Rummy puro: 300 en vez de 200 si cierras con rummy solo con tu mano, sin a\u00F1adir cartas a combinaciones existentes ni recuperar comodines.",
              "- Otros 100 si terminas antes de que ning\u00FAn rival haya hecho su primera bajada. Esta bonificaci\u00F3n no exige cerrar con rummy.",
              "Al acabar una ronda en la que alguien alcanza 1000 puntos, gana quien tenga m\u00E1s. Si el primer puesto est\u00E1 empatado, se juega otra ronda.",
              "S lee los resultados, E cuenta las cartas de cada mano y las que quedan para robar, y T indica de qui\u00E9n es el turno."),
            rule_section(:blocked, "Si se agota el mazo",
              "Cuando se agota el mazo, se barajan los descartes para volver a robar. El descarte m\u00E1s reciente queda disponible con Shift+D. Si ya no hay de d\u00F3nde robar, puedes bajar y a\u00F1adir cartas sin robar antes.",
              "Si no se puede robar y transcurren dos rondas completas de turnos sin que nadie baje o a\u00F1ada una carta de su mano, termina la ronda. Todos conservan los puntos de sus jugadas, pero no hay ganador de ronda ni bonificaciones por terminar."),
            rule_section(:variants, "Variantes",
              "Al crear la mesa puedes cambiar las reglas siguientes. El resto de la partida se mantiene igual."),
            rule_section(:limits, "Primera bajada y meta de puntos",
              "Puedes cambiar el m\u00EDnimo de 30 para la primera bajada. Debes alcanzar el m\u00EDnimo elegido antes de a\u00F1adir cartas a la mesa y de empezar a tomar descartes.",
              "Tambi\u00E9n puedes sustituir la meta de 1000 por otra cantidad. El resultado de la partida sigue decidi\u00E9ndose al terminar una ronda."),
            rule_section(:discard, "Variantes de robo y descarte",
              "En lugar de tomar solo el \u00FAltimo descarte puedes elegir estas reglas:",
              "- Tomar descartes anteriores: D lee todos los disponibles y Shift+D abre la lista, empezando por el m\u00E1s reciente. Elige con las flechas y confirma con Enter. Recibes esa carta y todas las descartadas despu\u00E9s: elegir la tercera recoge la tercera, segunda y primera. Si solo hay una, Shift+D la toma directamente.",
              "- No tomar descartes: robas con Espacio y sigues terminando el turno con Supr para descartar.",
              "- Jugar sin descartes: despu\u00E9s de robar y jugar, termina el turno con Shift+F. Todas las cartas que no hayas bajado quedan en la mano."),
            rule_section(:identities, "Grupos de cartas id\u00E9nticas",
              "Esta opci\u00F3n permite grupos de tres o cuatro cartas id\u00E9nticas, como tres nueves de tr\u00E9boles. Cada carta de esos grupos vale 10 puntos m\u00E1s de lo habitual, tambi\u00E9n para alcanzar la primera bajada."),
            rule_section(:rounding, "Puntuaci\u00F3n sin redondeo",
              "Si desactivas el redondeo, los valores cambian as\u00ED:",
              "- Del dos al nueve se cuenta el n\u00FAmero de la carta, en lugar de 5.",
              "- El as antes del dos vale 1; en otras combinaciones o en la mano vale 11.",
              "- El diez y las figuras siguen valiendo 10.",
              "- El comod\u00EDn que queda en la mano sigue valiendo 20."),
            rule_section(:manipulation, "Reorganizar las combinaciones",
              "Con esta opci\u00F3n puedes reorganizar la mesa. Antes debes haber robado y completado tu primera bajada. Pulsa C, selecciona una combinaci\u00F3n y abre el men\u00FA contextual. All\u00ED puedes unir combinaciones o recoger una combinaci\u00F3n entera o cartas concretas.",
              "Las cartas recogidas se pueden usar en otro lugar, con estas restricciones:",
              "- De una escalera puedes recoger una carta de cualquiera de sus extremos si quedan al menos tres consecutivas. De 4, 5, 6, 7 de corazones puedes tomar el cuatro o el siete.",
              "- De un grupo de cuatro valores iguales puedes recoger una carta.",
              "- Solo puedes recoger una combinaci\u00F3n entera si no contiene comod\u00EDn. Si lo tiene, primero debes recuperarlo sustituy\u00E9ndolo por la carta adecuada.",
              "Retirar otras cartas no puede cambiar el valor que representa un comod\u00EDn.",
              "Para unir, elige esa acci\u00F3n en el men\u00FA y despu\u00E9s la segunda combinaci\u00F3n. Juntas deben seguir siendo v\u00E1lidas. Puedes unir 4, 5, 6 de corazones con 7, 8, 9 de corazones, pero no dos escaleras separadas por una carta que falta.",
              "Cada carta recogida que no vuelvas a jugar antes de terminar el turno cuesta 300 puntos de penalizaci\u00F3n. Lo mismo se aplica al comod\u00EDn recuperado: dos cartas sin usar cuestan 600. Pueden quedarse en tu mano y, tras la penalizaci\u00F3n, se tratan como las dem\u00E1s. Descartarlas no cuenta como volver a jugarlas.",
              "Recoger cartas de la mesa resta su valor de tus puntos; al volver a bajarlas los recuperas. Unir combinaciones no punt\u00FAa por s\u00ED solo. Recoger una sola carta de la mesa ya impide cerrar con rummy puro."),
            rule_section(:elimination, "Modo eliminaci\u00F3n",
              "Aqu\u00ED intentas tener pocos puntos. Bajar, a\u00F1adir o recoger cartas no suma ni resta, aunque la primera bajada sigue necesitando su m\u00EDnimo. Quien termina la ronda no recibe puntos por cartas; los dem\u00E1s a\u00F1aden el valor de las que conserven. Las penalizaciones se suman en vez de restarse.",
              "En lugar de bonificaciones por rummy, se multiplica el valor de las cartas restantes de los rivales:",
              "- Si cierras con rummy, lo cuentan doble.",
              "- Si cierras con rummy puro, lo cuentan triple.",
              "- Si adem\u00E1s de rummy puro ning\u00FAn rival hab\u00EDa hecho su primera bajada, lo cuentan cu\u00E1druple.",
              "Estos multiplicadores no aumentan las penalizaciones.",
              "Si la ronda se bloquea, todos a\u00F1aden el valor de las cartas de sus manos.",
              "Tras el recuento se elimina a quienes hayan alcanzado el l\u00EDmite, de 500 por defecto. Gana el \u00FAltimo jugador. Si todos alcanzan el l\u00EDmite en la misma ronda, gana el menor resultado; varios m\u00EDnimos iguales comparten la victoria."),
            rule_section(:time, "Tiempo y penalizaciones",
              "Con l\u00EDmite de tiempo debes terminar el turno antes del plazo. Si lo agotas, recibes 50 puntos de penalizaci\u00F3n y pasa el turno. Si a\u00FAn no hab\u00EDas robado, recibes adem\u00E1s una carta del mazo si hay alguna. Si ya hab\u00EDas robado, no tomas otra. No se descarta ninguna carta por agotar el tiempo.",
              "Las penalizaciones se acumulan. Agotar el tiempo con un comod\u00EDn recuperado sin usar cuesta 350 puntos. En la partida normal se restan; en eliminaci\u00F3n se suman."),
            rule_section(:controls, "Teclas de referencia",
              "Flechas: recorrer la mano o una lista abierta.",
              "Espacio: robar del mazo.",
              "D: consultar los descartes disponibles.",
              "Shift+D: tomar un descarte o abrir la lista para elegirlo.",
              "N: preparar una combinaci\u00F3n; pulsarlo otra vez inicia otra dentro de la misma bajada.",
              "Enter al preparar: marcar o desmarcar una carta.",
              "P: consultar las combinaciones preparadas y su valor.",
              "Shift+P: elegir una combinaci\u00F3n preparada para editarla o borrarla.",
              "F: bajar las combinaciones preparadas.",
              "Escape: cerrar una lista o cancelar la bajada preparada.",
              "Enter fuera de la preparaci\u00F3n: elegir d\u00F3nde a\u00F1adir la carta o recuperar un comod\u00EDn; si no encaja, puedes descartarla.",
              "Supr: descartar la carta y terminar el turno.",
              "Shift+F: terminar el turno en la variante sin descartes.",
              "C: abrir las combinaciones de la mesa.",
              "E: contar las cartas de los jugadores y las que quedan para robar.",
              "S: consultar los resultados.",
              "T: consultar de qui\u00E9n es el turno.",
              "Men\u00FA contextual en las combinaciones: recoger cartas o unir combinaciones, si la variante lo permite.",
              "Z: ir a la siguiente carta que encaje; con una sola posibilidad puede a\u00F1adirla directamente.",
              "Shift+Z: ir a la carta anterior que encaje; con una sola posibilidad puede a\u00F1adirla directamente.",
              "Shift+C: ordenar por palos; repetir para invertir el orden.",
              "Shift+H: ordenar por valores; repetir para invertir el orden.",
              "Shift+M: recuperar el orden de recepci\u00F3n.")
          ]
        when "pl"
          [
            rule_section(:table, "Cel gry",
              "W Remiku zbierasz pasuj\u0105ce do siebie karty i wyk\u0142adasz je na st\u00F3\u0142. Mo\u017Cesz te\u017C dok\u0142ada\u0107 karty do uk\u0142ad\u00F3w, kt\u00F3re ju\u017C tam le\u017C\u0105. Za zagrane karty zdobywasz punkty, a gdy pozb\u0119dziesz si\u0119 ca\u0142ej r\u0119ki, wygrywasz rund\u0119. Wyniki kolejnych rund si\u0119 sumuj\u0105. Ca\u0142\u0105 parti\u0119 wygrywa osoba z najwi\u0119ksz\u0105 liczb\u0105 punkt\u00F3w, gdy kto\u015B osi\u0105gnie 1000.",
              "Gra jest przeznaczona dla dw\u00F3ch do o\u015Bmiu os\u00F3b. Na pocz\u0105tku ka\u017Cdej rundy dostajesz czterna\u015Bcie kart.",
              "W r\u0119ce poruszasz si\u0119 strza\u0142kami. Shift+C uk\u0142ada karty wed\u0142ug kolor\u00F3w, a Shift+H wed\u0142ug warto\u015Bci. Ponowne u\u017Cycie tych skr\u00F3t\u00F3w odwraca kolejno\u015B\u0107. Je\u015Bli wolisz kolejno\u015B\u0107, w kt\u00F3rej dostawa\u0142e\u015B karty, przywr\u00F3cisz j\u0105 przez Shift+M."),
            rule_section(:combinations, "Jakie karty do siebie pasuj\u0105",
              "Na st\u00F3\u0142 wyk\u0142adasz uk\u0142ady z\u0142o\u017Cone z co najmniej trzech kart. S\u0105 dwa rodzaje uk\u0142ad\u00F3w:",
              "- Seria to kolejne karty w jednym kolorze, na przyk\u0142ad 5, 6 i 7 kier. Do takiej serii pasuje potem 4 kier z jednej strony lub 8 kier z drugiej.",
              "- Zestaw tworz\u0105 trzy albo cztery karty tej samej warto\u015Bci w r\u00F3\u017Cnych kolorach. Mog\u0105 to by\u0107 na przyk\u0142ad dama kier, dama karo i dama pik. Do nich da si\u0119 do\u0142o\u017Cy\u0107 dam\u0119 trefl.",
              "As mo\u017Ce sta\u0107 przed dw\u00F3jk\u0105 lub po kr\u00F3lu. Pasuj\u0105 wi\u0119c as, 2, 3 oraz dama, kr\u00F3l, as. Nie mo\u017Cna po\u0142\u0105czy\u0107 w ten spos\u00F3b kr\u00F3la, asa i dw\u00F3jki.",
              "Joker zast\u0119puje jedn\u0105 brakuj\u0105c\u0105 kart\u0119. W ka\u017Cdym uk\u0142adzie mo\u017Ce by\u0107 tylko jeden joker i musz\u0105 mu towarzyszy\u0107 przynajmniej dwie zwyk\u0142e karty. W serii jego znaczenie zale\u017Cy od kolejno\u015Bci, w kt\u00F3rej wybierzesz karty: joker, 3 pik, 4 pik daje seri\u0119 od dw\u00F3jki, a 3 pik, 4 pik, joker \u2014 seri\u0119 ko\u0144cz\u0105c\u0105 si\u0119 pi\u0105tk\u0105."),
            rule_section(:turn, "Przebieg tury",
              "Na pocz\u0105tku tury dobierz jedn\u0105 kart\u0119 Spacj\u0105. Gdy masz ju\u017C za sob\u0105 pierwsze wy\u0142o\u017Cenie, mo\u017Cesz zamiast tego wzi\u0105\u0107 ostatni\u0105 kart\u0119 odrzucon\u0105 przez innego gracza. D pozwala j\u0105 odczyta\u0107, a Shift+D j\u0105 dobiera.",
              "Po dobraniu mo\u017Cesz wyk\u0142ada\u0107 uk\u0142ady. Je\u017Celi masz ju\u017C za sob\u0105 pierwsze wy\u0142o\u017Cenie, wolno ci r\u00F3wnie\u017C dok\u0142ada\u0107 karty do uk\u0142ad\u00F3w w\u0142asnych i pozosta\u0142ych graczy. W jednej turze mo\u017Cesz zrobi\u0107 to kilka razy. Nie musisz od razu u\u017Cywa\u0107 dobranej karty ani wyk\u0142ada\u0107 czegokolwiek, je\u015Bli wolisz poczeka\u0107.",
              "Na koniec wybierz kart\u0119 do odrzucenia i naci\u015Bnij Delete. Odrzucenie ko\u0144czy twoj\u0105 tur\u0119; teraz gra nast\u0119pna osoba.",
              "Je\u015Bli pozb\u0119dziesz si\u0119 wszystkich kart przez wy\u0142o\u017Cenie lub do\u0142o\u017Cenie, runda ko\u0144czy si\u0119 od razu. Nie trzeba zostawia\u0107 sobie ostatniej karty do odrzucenia."),
            rule_section(:opening, "Pierwsze wy\u0142o\u017Cenie",
              "Twoje pierwsze wy\u0142o\u017Cenie w ka\u017Cdej rundzie musi by\u0107 warte przynajmniej 30 punkt\u00F3w. Mo\u017Ce to by\u0107 jeden uk\u0142ad albo kilka wy\u0142o\u017Conych razem. Dopiero po tym wy\u0142o\u017Ceniu mo\u017Cesz dok\u0142ada\u0107 karty do uk\u0142ad\u00F3w na stole, a od nast\u0119pnej tury tak\u017Ce dobiera\u0107 karty odrzucone.",
              "\u017Beby przygotowa\u0107 uk\u0142ad, naci\u015Bnij N. Odszukaj pierwsz\u0105 kart\u0119 strza\u0142kami i zaznacz j\u0105 Enterem, potem wybierz w ten sam spos\u00F3b kolejne. Seri\u0119 zaznaczaj od najni\u017Cszej do najwy\u017Cszej karty: dla uk\u0142adu 5, 6, 7 najpierw pi\u0105tk\u0119, potem sz\u00F3stk\u0119 i si\u00F3demk\u0119. Ponowny Enter na zaznaczonej karcie usuwa j\u0105 z przygotowywanego uk\u0142adu.",
              "Je\u015Bli potrzebujesz kilku uk\u0142ad\u00F3w do osi\u0105gni\u0119cia progu, po zaznaczeniu pierwszego naci\u015Bnij ponownie N i wybierz karty nast\u0119pnego. Niczego jeszcze nie wyk\u0142adasz. P odczytuje przygotowane uk\u0142ady i ich warto\u015B\u0107, wi\u0119c mo\u017Cesz sprawdzi\u0107, czy masz ju\u017C wystarczaj\u0105co du\u017Co punkt\u00F3w.",
              "Gotowe uk\u0142ady wyk\u0142adasz razem klawiszem F. Gdy czego\u015B brakuje lub kt\u00F3ry\u015B uk\u0142ad jest niepoprawny, us\u0142yszysz przyczyn\u0119 i mo\u017Cesz zmieni\u0107 wyb\u00F3r. Shift+P otwiera list\u0119 przygotowanych uk\u0142ad\u00F3w; Enter przy wybranym pozwala go poprawi\u0107 albo usun\u0105\u0107. Escape podczas przygotowywania rezygnuje z ca\u0142ego wy\u0142o\u017Cenia.",
              "Po pierwszym wy\u0142o\u017Ceniu nie obowi\u0105zuje ju\u017C minimalna liczba punkt\u00F3w. Kolejne uk\u0142ady tworzysz tymi samymi klawiszami. Mo\u017Cesz te\u017C od razu dok\u0142ada\u0107 do kart na stole, jeszcze w tej samej turze."),
            rule_section(:laying, "Dok\u0142adanie do uk\u0142ad\u00F3w",
              "C otwiera list\u0119 uk\u0142ad\u00F3w na stole. Przegl\u0105daj j\u0105 strza\u0142kami; Enter odczytuje wybrany uk\u0142ad, a Escape wraca do r\u0119ki.",
              "\u017Beby do\u0142o\u017Cy\u0107 kart\u0119, wybierz j\u0105 w r\u0119ce i naci\u015Bnij Enter, nie rozpoczynaj\u0105c nowego uk\u0142adu przez N. Zobaczysz miejsca, do kt\u00F3rych karta pasuje. Wybierz jedno z nich i zatwierd\u017A Enterem.",
              "Z wyszukuje nast\u0119pn\u0105 kart\u0119, kt\u00F3r\u0105 mo\u017Cna do\u0142o\u017Cy\u0107, a Shift+Z poprzedni\u0105. Przy jednej pasuj\u0105cej karcie skr\u00F3t mo\u017Ce te\u017C od razu j\u0105 do\u0142o\u017Cy\u0107.",
              "Serie mo\u017Cna przed\u0142u\u017Ca\u0107 na obu ko\u0144cach. Do trzech kart tej samej warto\u015Bci mo\u017Cna do\u0142o\u017Cy\u0107 czwarty, brakuj\u0105cy kolor. Sam joker nie s\u0142u\u017Cy do przed\u0142u\u017Cania uk\u0142adu: trzeba wy\u0142o\u017Cy\u0107 go w nowym uk\u0142adzie z co najmniej dwiema zwyk\u0142ymi kartami."),
            rule_section(:joker, "Jak odzyska\u0107 jokera",
              "Po pierwszym wy\u0142o\u017Ceniu mo\u017Cesz zabra\u0107 jokera ze sto\u0142u, k\u0142ad\u0105c w jego miejsce kart\u0119, kt\u00F3r\u0105 zast\u0119puje. Na przyk\u0142ad do serii joker, 3 pik, 4 pik potrzebujesz dw\u00F3jki pik. Wybierz j\u0105 w r\u0119ce, naci\u015Bnij Enter, a potem zatwierd\u017A pozycj\u0119 \u201EZast\u0105p jokera\u201D przy tym uk\u0142adzie. Dw\u00F3jka zostanie na stole, a joker trafi do twojej r\u0119ki.",
              "Je\u015Bli na stole le\u017C\u0105 7 kier, 7 karo i joker, nie wiadomo jeszcze, czy joker zast\u0119puje 7 pik, czy 7 trefl. \u017Beby go odzyska\u0107, trzeba najpierw do\u0142o\u017Cy\u0107 jedn\u0105 z tych kart. Gdy do\u0142o\u017Cysz 7 pik, joker b\u0119dzie zast\u0119powa\u0142 ju\u017C tylko 7 trefl \u2014 i w\u0142a\u015Bnie t\u0105 kart\u0105 mo\u017Cesz go zast\u0105pi\u0107.",
              "Je\u015Bli do ko\u0144ca tury nie wy\u0142o\u017Cysz odzyskanego jokera w nowym uk\u0142adzie, stracisz 300 punkt\u00F3w. Kara obowi\u0105zuje r\u00F3wnie\u017C wtedy, gdy go odrzucisz. Dostajesz j\u0105 tylko raz; w nast\u0119pnych turach mo\u017Cesz korzysta\u0107 z jokera tak jak z pozosta\u0142ych kart."),
            rule_section(:values, "Ile warte s\u0105 karty",
              "Przy liczeniu pierwszego wy\u0142o\u017Cenia i punkt\u00F3w za zagrane karty obowi\u0105zuj\u0105 nast\u0119puj\u0105ce warto\u015Bci:",
              "- Ka\u017Cda karta od dw\u00F3jki do dziewi\u0105tki jest warta 5 punkt\u00F3w.",
              "- Dziesi\u0105tka, walet, dama i kr\u00F3l daj\u0105 po 10 punkt\u00F3w.",
              "- As jest wart 15 punkt\u00F3w, chyba \u017Ce rozpoczyna seri\u0119 przed dw\u00F3jk\u0105 \u2014 wtedy daje 5 punkt\u00F3w.",
              "Wy\u0142o\u017Cony joker daje tyle punkt\u00F3w, co karta, kt\u00F3r\u0105 zast\u0119puje. W serii 3, 4, joker zast\u0119puje pi\u0105tk\u0119, wi\u0119c ca\u0142y uk\u0142ad jest wart 15 punkt\u00F3w. Przy liczeniu kart pozosta\u0142ych w r\u0119ce joker jest wart 20 punkt\u00F3w, a as 15."),
            rule_section(:normal, "Punktacja i koniec gry",
              "Zbierasz punkty za ka\u017Cd\u0105 wy\u0142o\u017Con\u0105 i do\u0142o\u017Con\u0105 kart\u0119. Gdy kto\u015B opr\u00F3\u017Cni r\u0119k\u0119, runda si\u0119 ko\u0144czy. Pozostali zachowuj\u0105 zdobyte punkty, a zwyci\u0119zca dostaje dodatkowo sum\u0119 warto\u015Bci wszystkich kart, kt\u00F3re zosta\u0142y im w r\u0119kach.",
              "Za zako\u0144czenie rundy mo\u017Cesz dosta\u0107 premie:",
              "- Remik daje 200 punkt\u00F3w. Ko\u0144czysz w ten spos\u00F3b, je\u015Bli twoje pierwsze wy\u0142o\u017Cenie i pozbycie si\u0119 ostatniej karty nast\u0105pi\u0105 w tej samej turze.",
              "- Czysty remik daje 300 punkt\u00F3w zamiast 200. Musisz sko\u0144czy\u0107 remikiem wy\u0142\u0105cznie z w\u0142asnej r\u0119ki, bez dok\u0142adania do istniej\u0105cych uk\u0142ad\u00F3w i bez odzyskiwania joker\u00F3w.",
              "- Dodatkowe 100 punkt\u00F3w dostajesz, je\u015Bli ko\u0144czysz rund\u0119, zanim ktokolwiek z przeciwnik\u00F3w wy\u0142o\u017Cy swoje pierwsze karty. Ta premia przys\u0142uguje tak\u017Ce wtedy, gdy nie ko\u0144czysz remikiem.",
              "Po rundzie, w kt\u00F3rej kto\u015B osi\u0105gnie 1000 punkt\u00F3w, wygrywa osoba z najwi\u0119ksz\u0105 liczb\u0105 punkt\u00F3w. Przy remisie na pierwszym miejscu rozgrywacie nast\u0119pn\u0105 rund\u0119.",
              "S odczytuje punktacj\u0119. Pod E sprawdzisz liczb\u0119 kart w r\u0119kach graczy i liczb\u0119 kart do dobrania, a pod T \u2014 czyja jest tura."),
            rule_section(:blocked, "Gdy zabraknie kart do dobierania",
              "Po wyczerpaniu talii wcze\u015Bniej odrzucone karty s\u0105 tasowane i ponownie s\u0142u\u017C\u0105 do dobierania. Ostatnia odrzucona karta nadal pozostaje dost\u0119pna pod Shift+D. Je\u015Bli nie ma ju\u017C sk\u0105d dobra\u0107 karty, mo\u017Cesz wyk\u0142ada\u0107 i dok\u0142ada\u0107 bez dobierania.",
              "Je\u015Bli nie ma sk\u0105d dobra\u0107 kart i przez dwie pe\u0142ne kolejki nikt nie wy\u0142o\u017Cy ani nie do\u0142o\u017Cy karty z r\u0119ki, runda si\u0119 ko\u0144czy. Ka\u017Cdy zachowuje punkty zdobyte za wy\u0142o\u017Cenia, lecz nie ma zwyci\u0119zcy rundy ani premii za jej zako\u0144czenie."),
            rule_section(:variants, "Warianty gry",
              "Przy tworzeniu sto\u0142u mo\u017Cesz zmieni\u0107 poni\u017Csze zasady. Pozosta\u0142a cz\u0119\u015B\u0107 gry przebiega tak samo."),
            rule_section(:limits, "Pr\u00F3g pierwszego wy\u0142o\u017Cenia i limit punkt\u00F3w",
              "Mo\u017Cesz ustali\u0107 inn\u0105 warto\u015B\u0107 pierwszego wy\u0142o\u017Cenia ni\u017C 30 punkt\u00F3w. Zanim zaczniesz dok\u0142ada\u0107 karty do uk\u0142ad\u00F3w na stole i dobiera\u0107 karty odrzucone, musisz wy\u0142o\u017Cy\u0107 uk\u0142ady warte co najmniej tyle, ile wynosi wybrany pr\u00F3g.",
              "Limit punkt\u00F3w okre\u015Bla, kiedy ko\u0144czy si\u0119 ca\u0142a partia. Mo\u017Cesz zmieni\u0107 go z 1000 na inn\u0105 liczb\u0119; wynik nadal rozstrzyga si\u0119 dopiero po zako\u0144czeniu rundy."),
            rule_section(:discard, "Inne sposoby dobierania i odrzucania",
              "Zamiast dobierania tylko ostatniej odrzuconej karty mo\u017Cesz wybra\u0107 jedn\u0105 z poni\u017Cszych zasad:",
              "- Dobieranie tak\u017Ce wcze\u015Bniejszych odrzut\u00F3w. D odczytuje wszystkie dost\u0119pne karty, a Shift+D otwiera ich list\u0119. Najnowsza karta jest pierwsza. Wybierz kart\u0119 strza\u0142kami i naci\u015Bnij Enter: dostaniesz j\u0105 razem ze wszystkimi odrzuconymi p\u00F3\u017Aniej. Wyb\u00F3r trzeciej karty oznacza wi\u0119c dobranie trzeciej, drugiej i pierwszej. Je\u015Bli dost\u0119pna jest tylko jedna karta, Shift+D bierze j\u0105 od razu.",
              "- Bez dobierania odrzut\u00F3w. Dobierasz Spacj\u0105, a na koniec tury nadal odrzucasz kart\u0119 przez Delete.",
              "- Bez odrzucania kart. Po dobraniu i swoich zagraniach ko\u0144czysz tur\u0119 skr\u00F3tem Shift+F. Wszystkie niewy\u0142o\u017Cone karty zostaj\u0105 w r\u0119ce."),
            rule_section(:identities, "Uk\u0142ady z identycznych kart",
              "Ta opcja pozwala u\u0142o\u017Cy\u0107 trzy lub cztery jednakowe karty, na przyk\u0142ad trzy dziewi\u0105tki trefl. Ka\u017Cda karta w takim uk\u0142adzie jest warta o 10 punkt\u00F3w wi\u0119cej ni\u017C zwykle. Ten dodatek liczy si\u0119 r\u00F3wnie\u017C przy pierwszym wy\u0142o\u017Ceniu."),
            rule_section(:rounding, "Punktacja bez zaokr\u0105glania",
              "Po wy\u0142\u0105czeniu zaokr\u0105glania obowi\u0105zuj\u0105 inne warto\u015Bci kart:",
              "- Karty od dw\u00F3jki do dziewi\u0105tki licz\u0105 si\u0119 zgodnie z liczb\u0105 na karcie, zamiast po 5 punkt\u00F3w.",
              "- As przed dw\u00F3jk\u0105 jest wart 1 punkt, a w pozosta\u0142ych uk\u0142adach i w r\u0119ce 11.",
              "- Dziesi\u0105tki i figury nadal daj\u0105 po 10 punkt\u00F3w.",
              "- Joker pozosta\u0142y w r\u0119ce jest wart 20 punkt\u00F3w."),
            rule_section(:manipulation, "Zabieranie i \u0142\u0105czenie uk\u0142ad\u00F3w",
              "Po w\u0142\u0105czeniu manipulacji uk\u0142adami mo\u017Cesz przebudowywa\u0107 to, co le\u017Cy na stole. Najpierw musisz dobra\u0107 kart\u0119 i mie\u0107 za sob\u0105 w\u0142asne pierwsze wy\u0142o\u017Cenie. Otw\u00F3rz st\u00F3\u0142 klawiszem C, wybierz uk\u0142ad i naci\u015Bnij klawisz menu kontekstowego. Znajdziesz tam \u0142\u0105czenie uk\u0142ad\u00F3w oraz zabieranie ca\u0142ego uk\u0142adu lub konkretnych kart.",
              "Zabrane karty mo\u017Cesz wykorzysta\u0107 w innym miejscu. To, co wolno zabra\u0107, zale\u017Cy od uk\u0142adu:",
              "- Z serii mo\u017Cesz zabra\u0107 kart\u0119 z pocz\u0105tku albo ko\u0144ca, je\u015Bli zostan\u0105 przynajmniej trzy kolejne karty. Przyk\u0142adowo z serii 4, 5, 6, 7 kier mo\u017Cesz wzi\u0105\u0107 czw\u00F3rk\u0119 lub si\u00F3demk\u0119.",
              "- Z zestawu czterech kart tej samej warto\u015Bci mo\u017Cesz zabra\u0107 jedn\u0105 kart\u0119.",
              "- Ca\u0142y uk\u0142ad wolno zabra\u0107 tylko wtedy, gdy nie ma w nim jokera. Je\u015Bli chcesz zabra\u0107 uk\u0142ad z jokerem, najpierw odzyskaj go przez podmian\u0119 odpowiedni\u0105 kart\u0105.",
              "Zabieranie innych kart nie mo\u017Ce zmienia\u0107 tego, co joker zast\u0119puje.",
              "Aby po\u0142\u0105czy\u0107 uk\u0142ady, wybierz w menu \u201EPo\u0142\u0105cz\u201D, a nast\u0119pnie drugi uk\u0142ad. Musz\u0105 razem tworzy\u0107 poprawn\u0105 ca\u0142o\u015B\u0107. Dwie serie 4, 5, 6 kier oraz 7, 8, 9 kier mo\u017Cna po\u0142\u0105czy\u0107, ale serii rozdzielonych brakuj\u0105c\u0105 kart\u0105 ju\u017C nie.",
              "Za ka\u017Cd\u0105 zabran\u0105 kart\u0119, kt\u00F3rej nie wykorzystasz ponownie do ko\u0144ca tury, dostajesz 300 punkt\u00F3w kary. Tak samo rozliczany jest odzyskany joker. Dwie niewykorzystane karty oznaczaj\u0105 wi\u0119c 600 punkt\u00F3w kary. Karty mog\u0105 zosta\u0107 w r\u0119ce; po naliczeniu kary traktujesz je ju\u017C jak pozosta\u0142e. Samo odrzucenie zabranej karty nie zast\u0119puje jej ponownego wy\u0142o\u017Cenia.",
              "Zabranie kart ze sto\u0142u odbiera ci tyle punkt\u00F3w, ile s\u0105 warte. Po ponownym wy\u0142o\u017Ceniu zn\u00F3w je zdobywasz. \u0141\u0105czenie uk\u0142ad\u00F3w samo w sobie nie daje punkt\u00F3w. Zabranie cho\u0107by jednej karty ze sto\u0142u wyklucza zako\u0144czenie rundy czystym remikiem."),
            rule_section(:elimination, "Tryb eliminacyjny",
              "W tym wariancie starasz si\u0119 mie\u0107 jak najmniej punkt\u00F3w. Za wyk\u0142adanie, dok\u0142adanie i zabieranie kart ze sto\u0142u nie dostajesz ani nie tracisz punkt\u00F3w. Nadal obowi\u0105zuje pr\u00F3g pierwszego wy\u0142o\u017Cenia. Osoba ko\u0144cz\u0105ca rund\u0119 nie dostaje punkt\u00F3w za karty, a pozostali dopisuj\u0105 sobie warto\u015B\u0107 tego, co zosta\u0142o im w r\u0119kach. Kary dodaje si\u0119 do wyniku, zamiast je odejmowa\u0107.",
              "Zamiast premii za remika zwi\u0119ksza si\u0119 punkty, kt\u00F3re przeciwnicy dostaj\u0105 za karty pozosta\u0142e w r\u0119kach:",
              "- Gdy ko\u0144czysz remikiem, przeciwnicy licz\u0105 te punkty podw\u00F3jnie.",
              "- Gdy ko\u0144czysz czystym remikiem, licz\u0105 je potr\u00F3jnie.",
              "- Je\u015Bli przy czystym remiku nikt inny nie zd\u0105\u017Cy\u0142 zrobi\u0107 pierwszego wy\u0142o\u017Cenia, przeciwnicy licz\u0105 swoje karty poczw\u00F3rnie.",
              "Te mno\u017Cniki nie powi\u0119kszaj\u0105 kar.",
              "Gdy runda zostanie zablokowana, wszyscy doliczaj\u0105 warto\u015B\u0107 kart, kt\u00F3re zosta\u0142y im w r\u0119kach.",
              "Po rozliczeniu rundy odpadaj\u0105 gracze, kt\u00F3rzy osi\u0105gn\u0119li limit punkt\u00F3w; domy\u015Blnie jest to 500. Wygrywa ostatnia pozosta\u0142a osoba. Je\u015Bli w jednej rundzie wszyscy osi\u0105gn\u0105 limit, zwyci\u0119\u017Ca ten, kto ma najmniej punkt\u00F3w. R\u00F3wne najni\u017Csze wyniki oznaczaj\u0105 wsp\u00F3lne zwyci\u0119stwo."),
            rule_section(:time, "Czas na ruch i kary",
              "Po w\u0142\u0105czeniu limitu czasu trzeba zd\u0105\u017Cy\u0107 zako\u0144czy\u0107 tur\u0119. Po jego przekroczeniu dostajesz 50 punkt\u00F3w kary, a kolej przechodzi do nast\u0119pnej osoby. Je\u015Bli jeszcze nie dobiera\u0142e\u015B, dostajesz tak\u017Ce jedn\u0105 kart\u0119 z talii, o ile jest dost\u0119pna. Gdy karta by\u0142a ju\u017C dobrana, nie dobierasz drugiej. Nie odrzucasz karty za przekroczony czas.",
              "Kary si\u0119 sumuj\u0105. Przekroczenie czasu z jednym niewykorzystanym jokerem zabranym ze sto\u0142u oznacza \u0142\u0105cznie 350 punkt\u00F3w kary. W zwyk\u0142ej grze odejmuje si\u0119 je od wyniku, a w eliminacyjnej dodaje."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: przegl\u0105daj karty w r\u0119ce lub pozycje otwartej listy.",
              "Spacja: dobierz kart\u0119 z talii.",
              "D: odczytaj dost\u0119pne karty odrzucone.",
              "Shift+D: dobierz odrzut albo otw\u00F3rz list\u0119 odrzut\u00F3w do wyboru.",
              "N: zacznij przygotowywa\u0107 uk\u0142ad; ponownie naci\u015Bni\u0119te rozpoczyna nast\u0119pny uk\u0142ad w tym samym wy\u0142o\u017Ceniu.",
              "Enter podczas przygotowywania uk\u0142adu: zaznacz lub odznacz kart\u0119.",
              "P: odczytaj przygotowane uk\u0142ady i ich warto\u015B\u0107.",
              "Shift+P: wybierz przygotowany uk\u0142ad do poprawienia lub usuni\u0119cia.",
              "F: wy\u0142\u00F3\u017C przygotowane uk\u0142ady.",
              "Escape: zamknij otwart\u0105 list\u0119 lub anuluj przygotowywane wy\u0142o\u017Cenie.",
              "Enter na karcie poza przygotowywaniem uk\u0142adu: wybierz do\u0142o\u017Cenie lub odzyskanie jokera; je\u015Bli karta nigdzie nie pasuje, mo\u017Cesz j\u0105 odrzuci\u0107.",
              "Delete: odrzu\u0107 wybran\u0105 kart\u0119 i zako\u0144cz tur\u0119.",
              "Shift+F: zako\u0144cz tur\u0119 w wariancie bez odrzucania.",
              "C: otw\u00F3rz list\u0119 uk\u0142ad\u00F3w na stole.",
              "E: odczytaj liczb\u0119 kart graczy oraz kart do dobrania.",
              "S: odczytaj wyniki.",
              "T: sprawd\u017A, czyja jest tura.",
              "Klawisz menu kontekstowego na li\u015Bcie uk\u0142ad\u00F3w: wybierz zabranie kart lub po\u0142\u0105czenie uk\u0142ad\u00F3w, je\u015Bli ten wariant jest w\u0142\u0105czony.",
              "Z: przejd\u017A do nast\u0119pnej pasuj\u0105cej karty; przy jednej mo\u017Cliwo\u015Bci skr\u00F3t mo\u017Ce od razu j\u0105 do\u0142o\u017Cy\u0107.",
              "Shift+Z: przejd\u017A do poprzedniej pasuj\u0105cej karty; przy jednej mo\u017Cliwo\u015Bci skr\u00F3t mo\u017Ce od razu j\u0105 do\u0142o\u017Cy\u0107.",
              "Shift+C: sortuj karty wed\u0142ug kolor\u00F3w; ponownie \u2014 w odwrotnej kolejno\u015Bci.",
              "Shift+H: sortuj karty wed\u0142ug warto\u015Bci; ponownie \u2014 w odwrotnej kolejno\u015Bci.",
              "Shift+M: przywr\u00F3\u0107 kolejno\u015B\u0107 otrzymywania kart.")
          ]
        when "ru"
          [
            rule_section(:table, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0440\u0443\u043C\u043C\u0438 \u0432\u044B \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043A\u0430\u0440\u0442 \u0438 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0435 \u0438\u0445 \u043D\u0430 \u0441\u0442\u043E\u043B. \u041A \u0443\u0436\u0435 \u043B\u0435\u0436\u0430\u0449\u0438\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F\u043C \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u043A\u0430\u0440\u0442\u044B. \u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043E\u0447\u043A\u0438, \u0430 \u0432\u044B\u0445\u043E\u0434 \u0431\u0435\u0437 \u043A\u0430\u0440\u0442 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0440\u0430\u0443\u043D\u0434. \u041E\u0447\u043A\u0438 \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F: \u043A\u043E\u0433\u0434\u0430 \u043A\u0442\u043E-\u043D\u0438\u0431\u0443\u0434\u044C \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0435\u0442 1000, \u043F\u043E\u0431\u0435\u0434\u0438\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u043E\u0431\u0449\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442.",
              "\u0418\u0433\u0440\u0430\u044E\u0442 \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0447\u0435\u043B\u043E\u0432\u0435\u043A. \u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0440\u0430\u0443\u043D\u0434\u0430 \u0443 \u0432\u0441\u0435\u0445 \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u043A\u0430\u0440\u0442.",
              "\u041F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438. Shift+C \u0441\u043E\u0440\u0442\u0438\u0440\u0443\u0435\u0442 \u0435\u0451 \u043F\u043E \u043C\u0430\u0441\u0442\u044F\u043C, Shift+H \u2014 \u043F\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0443; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439. Shift+M \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442."),
            rule_section(:combinations, "\u0414\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F",
              "\u041D\u0430 \u0441\u0442\u043E\u043B \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0438\u0437 \u0442\u0440\u0451\u0445 \u043A\u0430\u0440\u0442. \u0415\u0441\u0442\u044C \u0434\u0432\u0430 \u0432\u0438\u0434\u0430:",
              "- \u0420\u044F\u0434 \u2014 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 5, 6, 7 \u0447\u0435\u0440\u0432\u0435\u0439. \u041F\u043E\u0437\u0436\u0435 \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u043A\u043E\u0439 \u0441 \u043E\u0434\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0446\u0430 \u0438\u043B\u0438 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u043E\u0439 \u0441 \u0434\u0440\u0443\u0433\u043E\u0433\u043E.",
              "- \u0413\u0440\u0443\u043F\u043F\u0430 \u2014 \u0442\u0440\u0438 \u0438\u043B\u0438 \u0447\u0435\u0442\u044B\u0440\u0435 \u043A\u0430\u0440\u0442\u044B \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430 \u0440\u0430\u0437\u043D\u044B\u0445 \u043C\u0430\u0441\u0442\u0435\u0439. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0434\u0430\u043C\u044B \u0447\u0435\u0440\u0432\u0435\u0439, \u0431\u0443\u0431\u0435\u043D \u0438 \u043F\u0438\u043A; \u043A \u043D\u0438\u043C \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0434\u0430\u043C\u0443 \u0442\u0440\u0435\u0444.",
              "\u0422\u0443\u0437 \u043C\u043E\u0436\u0435\u0442 \u0441\u0442\u043E\u044F\u0442\u044C \u043F\u0435\u0440\u0435\u0434 \u0434\u0432\u043E\u0439\u043A\u043E\u0439 \u0438\u043B\u0438 \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u0440\u043E\u043B\u044F: \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 A, 2, 3 \u0438 \u0434\u0430\u043C\u0430, \u043A\u043E\u0440\u043E\u043B\u044C, \u0442\u0443\u0437. \u041F\u0435\u0440\u0435\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 \u0442\u0443\u0437\u0430, \u043A\u0430\u043A \u0432 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u043A\u043E\u0440\u043E\u043B\u044C, \u0442\u0443\u0437, \u0434\u0432\u043E\u0439\u043A\u0430, \u0437\u0430\u043F\u0440\u0435\u0449\u0451\u043D.",
              "\u0414\u0436\u043E\u043A\u0435\u0440 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043E\u0434\u043D\u0443 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443. \u0412 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u0438\u043D \u0434\u0436\u043E\u043A\u0435\u0440 \u0438 \u043A\u0430\u043A \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0434\u0432\u0435 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B. \u0412 \u0440\u044F\u0434\u0443 \u0435\u0433\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043F\u043E\u0440\u044F\u0434\u043A\u0430 \u0432\u044B\u0431\u043E\u0440\u0430: \u0434\u0436\u043E\u043A\u0435\u0440, 3 \u043F\u0438\u043A, 4 \u043F\u0438\u043A \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u0434\u0432\u043E\u0439\u043A\u0438, \u0430 3 \u043F\u0438\u043A, 4 \u043F\u0438\u043A, \u0434\u0436\u043E\u043A\u0435\u0440 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u044F\u0442\u0451\u0440\u043A\u043E\u0439."),
            rule_section(:turn, "\u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0445\u043E\u0434\u0430",
              "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u043E\u0434\u043D\u0443 \u043A\u0430\u0440\u0442\u0443 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. \u041F\u043E\u0441\u043B\u0435 \u0441\u0432\u043E\u0435\u0433\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0432\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E \u0431\u0440\u0430\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u043D\u0443\u044E \u0434\u0440\u0443\u0433\u0438\u043C \u0438\u0433\u0440\u043E\u043A\u043E\u043C \u043A\u0430\u0440\u0442\u0443. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 D \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0435\u0451, Shift+D \u0431\u0435\u0440\u0451\u0442.",
              "\u041F\u043E\u0441\u043B\u0435 \u0434\u043E\u0431\u043E\u0440\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F. \u0415\u0441\u043B\u0438 \u043F\u0435\u0440\u0432\u043E\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435 \u0443\u0436\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043E, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0438 \u043A \u0441\u0432\u043E\u0438\u043C, \u0438 \u043A \u0447\u0443\u0436\u0438\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F\u043C \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u0417\u0430 \u0445\u043E\u0434 \u043C\u043E\u0436\u043D\u043E \u0434\u0435\u043B\u0430\u0442\u044C \u044D\u0442\u043E \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0430\u0437. \u041F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u0438\u043C\u0435\u043D\u043D\u043E \u0432\u0437\u044F\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u043E\u0439 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E, \u043A\u0430\u043A \u0438 \u0432\u043E\u043E\u0431\u0449\u0435 \u0447\u0442\u043E-\u043B\u0438\u0431\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C: \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u0434\u043E\u0436\u0434\u0430\u0442\u044C.",
              "\u0412 \u043A\u043E\u043D\u0446\u0435 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0434\u043B\u044F \u0441\u0431\u0440\u043E\u0441\u0430 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Delete. \u0421\u0431\u0440\u043E\u0441 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442 \u0445\u043E\u0434 \u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0434\u0430\u043B\u044C\u0448\u0435.",
              "\u0415\u0441\u043B\u0438 \u0432\u044B\u043B\u043E\u0436\u0438\u0432 \u0438\u043B\u0438 \u0434\u043E\u0431\u0430\u0432\u0438\u0432 \u043A\u0430\u0440\u0442\u044B, \u0432\u044B \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u043F\u0443\u0441\u0442\u043E\u0448\u0438\u043B\u0438 \u0440\u0443\u043A\u0443, \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E. \u0421\u043F\u0435\u0446\u0438\u0430\u043B\u044C\u043D\u043E \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u043A\u0430\u0440\u0442\u0443 \u0434\u043B\u044F \u0441\u0431\u0440\u043E\u0441\u0430 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F."),
            rule_section(:opening, "\u041F\u0435\u0440\u0432\u043E\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435",
              "\u0412 \u043A\u0430\u0436\u0434\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u043F\u0435\u0440\u0432\u043E\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u0441\u0442\u043E\u0438\u0442\u044C \u0445\u043E\u0442\u044F \u0431\u044B 30 \u043E\u0447\u043A\u043E\u0432. \u041C\u043E\u0436\u043D\u043E \u0432\u044B\u043B\u043E\u0436\u0438\u0442\u044C \u043E\u0434\u043D\u043E \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u0438\u043B\u0438 \u0441\u0440\u0430\u0437\u0443 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043A \u0441\u0442\u043E\u043B\u0443, \u0430 \u0441\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u2014 \u0431\u0440\u0430\u0442\u044C \u0441\u0431\u0440\u043E\u0441.",
              "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 N, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u0438\u0442\u044C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435. \u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u043F\u0435\u0440\u0432\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 Enter, \u0437\u0430\u0442\u0435\u043C \u0442\u0430\u043A \u0436\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435. \u0414\u043B\u044F \u0440\u044F\u0434\u0430 \u0441\u043E\u0431\u043B\u044E\u0434\u0430\u0439\u0442\u0435 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043E\u0442 \u043C\u043B\u0430\u0434\u0448\u0435\u0439 \u043A \u0441\u0442\u0430\u0440\u0448\u0435\u0439: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 5, \u0437\u0430\u0442\u0435\u043C 6, \u043F\u043E\u0442\u043E\u043C 7. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 Enter \u043D\u0430 \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u0435\u0451 \u0438\u0437 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0438.",
              "\u0415\u0441\u043B\u0438 \u0434\u043B\u044F \u043D\u0443\u0436\u043D\u043E\u0439 \u0441\u0443\u043C\u043C\u044B \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0439, \u043F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u043D\u043E\u0432\u0430 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 N \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435. \u041D\u0430 \u0441\u0442\u043E\u043B \u043F\u043E\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0443\u0445\u043E\u0434\u0438\u0442. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 P \u0447\u0438\u0442\u0430\u0435\u0442 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u0438 \u0438\u0445 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C, \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0441\u0443\u043C\u043C\u0443.",
              "\u0414\u043B\u044F \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0439 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u0438 \u0432\u0441\u0435\u0433\u043E \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u043D\u0430\u0436\u043C\u0438\u0442\u0435 F. \u0415\u0441\u043B\u0438 \u0441\u0443\u043C\u043C\u0430 \u043C\u0430\u043B\u0430 \u0438\u043B\u0438 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043D\u0435\u0432\u0435\u0440\u043D\u043E, \u0432\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043F\u0440\u0438\u0447\u0438\u043D\u0443 \u0438 \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u043E\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0432\u044B\u0431\u043E\u0440. Shift+P \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043F\u0438\u0441\u043E\u043A \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0439; Enter \u043D\u0430 \u043D\u0443\u0436\u043D\u043E\u043C \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0435\u0433\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0438\u0442\u044C. Escape \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0432\u0441\u044E \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0443.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u043D\u0443\u0436\u043D\u0430. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u0441\u043E\u0437\u0434\u0430\u044E\u0442\u0441\u044F \u0442\u0435\u043C\u0438 \u0436\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0430\u043C\u0438. \u0414\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u043A \u0441\u0442\u043E\u043B\u0443 \u043C\u043E\u0436\u043D\u043E \u0441\u0440\u0430\u0437\u0443, \u0435\u0449\u0451 \u0432 \u044D\u0442\u043E\u043C \u0436\u0435 \u0445\u043E\u0434\u0443."),
            rule_section(:laying, "\u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043A \u0441\u0442\u043E\u043B\u0443",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0439 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u041F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0435\u0433\u043E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438, Enter \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0435, Escape \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043A \u0440\u0443\u043A\u0435.",
              "\u0427\u0442\u043E\u0431\u044B \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u0443, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u0432 \u0440\u0443\u043A\u0435 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter, \u043D\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u044F \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0443 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 N. \u0418\u0433\u0440\u0430 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u043C\u0435\u0441\u0442\u0430. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0434\u043D\u043E \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter.",
              "Z \u043D\u0430\u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C, Shift+Z \u2014 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E. \u0415\u0441\u043B\u0438 \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430, \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448 \u043C\u043E\u0436\u0435\u0442 \u0441\u0440\u0430\u0437\u0443 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0435.",
              "\u0420\u044F\u0434\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442\u0441\u044F \u0441 \u043E\u0431\u043E\u0438\u0445 \u043A\u043E\u043D\u0446\u043E\u0432. \u041A \u0433\u0440\u0443\u043F\u043F\u0435 \u0438\u0437 \u0442\u0440\u0451\u0445 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0430\u044F \u043C\u0430\u0441\u0442\u044C. \u041E\u0434\u0438\u043D \u0434\u0436\u043E\u043A\u0435\u0440 \u043D\u0435 \u0441\u043B\u0443\u0436\u0438\u0442 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435\u043C: \u0435\u0433\u043E \u043D\u0443\u0436\u043D\u043E \u0432\u044B\u043B\u043E\u0436\u0438\u0442\u044C \u0432 \u043D\u043E\u0432\u043E\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u043A\u0430\u043A \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0441 \u0434\u0432\u0443\u043C\u044F \u043E\u0431\u044B\u0447\u043D\u044B\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438."),
            rule_section(:joker, "\u041A\u0430\u043A \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u0434\u0436\u043E\u043A\u0435\u0440\u0430",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u044C \u0434\u0436\u043E\u043A\u0435\u0440\u0430 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u043A\u0430\u0440\u0442\u043E\u0439, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043E\u043D \u043E\u0431\u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442. \u0414\u043B\u044F \u0440\u044F\u0434\u0430 \u0434\u0436\u043E\u043A\u0435\u0440, 3 \u043F\u0438\u043A, 4 \u043F\u0438\u043A \u043D\u0443\u0436\u043D\u0430 \u0434\u0432\u043E\u0439\u043A\u0430 \u043F\u0438\u043A. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0437\u0430\u043C\u0435\u043D\u0443 \u0434\u0436\u043E\u043A\u0435\u0440\u0430 \u0443 \u044D\u0442\u043E\u0433\u043E \u0440\u044F\u0434\u0430. \u0414\u0432\u043E\u0439\u043A\u0430 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u043D\u0430 \u0441\u0442\u043E\u043B\u0435, \u0430 \u0434\u0436\u043E\u043A\u0435\u0440 \u043F\u0435\u0440\u0435\u0439\u0434\u0451\u0442 \u0432 \u0432\u0430\u0448\u0443 \u0440\u0443\u043A\u0443.",
              "\u0412 \u0433\u0440\u0443\u043F\u043F\u0435 7 \u0447\u0435\u0440\u0432\u0435\u0439, 7 \u0431\u0443\u0431\u0435\u043D, \u0434\u0436\u043E\u043A\u0435\u0440 \u0435\u0433\u043E \u043C\u0430\u0441\u0442\u044C \u0435\u0449\u0451 \u043D\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0430: \u044D\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043F\u0438\u043A\u0430 \u0438\u043B\u0438 \u0442\u0440\u0435\u0444\u0430. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0443\u0436\u043D\u043E \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043E\u0434\u043D\u0443 \u0438\u0437 \u043D\u0438\u0445. \u041F\u043E\u0441\u043B\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u044F 7 \u043F\u0438\u043A \u0434\u0436\u043E\u043A\u0435\u0440 \u043E\u0434\u043D\u043E\u0437\u043D\u0430\u0447\u043D\u043E \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 7 \u0442\u0440\u0435\u0444, \u0438 \u0438\u043C\u0435\u043D\u043D\u043E \u044D\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u043E\u0439 \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C.",
              "\u0417\u0430\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0434\u0436\u043E\u043A\u0435\u0440\u0430 \u043D\u0443\u0436\u043D\u043E \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0445\u043E\u0434\u0430 \u0432\u044B\u043B\u043E\u0436\u0438\u0442\u044C \u0432 \u043D\u043E\u0432\u043E\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438, \u0438\u043D\u0430\u0447\u0435 \u0432\u044B \u043F\u043E\u0442\u0435\u0440\u044F\u0435\u0442\u0435 300 \u043E\u0447\u043A\u043E\u0432. \u0421\u0431\u0440\u043E\u0441 \u0434\u0436\u043E\u043A\u0435\u0440\u0430 \u043E\u0442 \u0448\u0442\u0440\u0430\u0444\u0430 \u043D\u0435 \u0441\u043F\u0430\u0441\u0430\u0435\u0442. \u0428\u0442\u0440\u0430\u0444 \u0432\u0437\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437; \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0445\u043E\u0434\u0430\u0445 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0443 \u0432\u0430\u0441 \u0434\u0436\u043E\u043A\u0435\u0440 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0440\u0443\u043A\u0438."),
            rule_section(:values, "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043A\u0430\u0440\u0442",
              "\u0414\u043B\u044F \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u0438 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0442\u0430\u043A\u0438\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F:",
              "- \u041A\u0430\u0440\u0442\u044B \u043E\u0442 \u0434\u0432\u043E\u0439\u043A\u0438 \u0434\u043E \u0434\u0435\u0432\u044F\u0442\u043A\u0438 \u2014 \u043F\u043E 5 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0414\u0435\u0441\u044F\u0442\u043A\u0430, \u0432\u0430\u043B\u0435\u0442, \u0434\u0430\u043C\u0430 \u0438 \u043A\u043E\u0440\u043E\u043B\u044C \u2014 \u043F\u043E 10.",
              "- \u0422\u0443\u0437 \u2014 15, \u043D\u043E \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0440\u044F\u0434\u0430 \u043F\u0435\u0440\u0435\u0434 \u0434\u0432\u043E\u0439\u043A\u043E\u0439 \u0442\u043E\u043B\u044C\u043A\u043E 5.",
              "\u0412\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0439 \u0434\u0436\u043E\u043A\u0435\u0440 \u0441\u0442\u043E\u0438\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0436\u0435, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u043C\u0430\u044F \u043A\u0430\u0440\u0442\u0430. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432 \u0440\u044F\u0434\u0443 3, 4, \u0434\u0436\u043E\u043A\u0435\u0440 \u043E\u043D \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u044F\u0442\u0451\u0440\u043A\u0443, \u0438 \u0432\u0435\u0441\u044C \u0440\u044F\u0434 \u0441\u0442\u043E\u0438\u0442 15. \u041F\u0440\u0438 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0435 \u043E\u0441\u0442\u0430\u0442\u043A\u043E\u0432 \u043D\u0430 \u0440\u0443\u043A\u0430\u0445 \u0434\u0436\u043E\u043A\u0435\u0440 \u0441\u0442\u043E\u0438\u0442 20, \u0430 \u0442\u0443\u0437 15."),
            rule_section(:normal, "\u041E\u0447\u043A\u0438 \u0438 \u043F\u043E\u0431\u0435\u0434\u0430",
              "\u041A\u0430\u0436\u0434\u0430\u044F \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u0430\u044F \u0438\u043B\u0438 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u0432\u0430\u043C \u043E\u0447\u043A\u0438. \u041A\u043E\u0433\u0434\u0430 \u043A\u0442\u043E-\u0442\u043E \u0432\u044B\u0445\u043E\u0434\u0438\u0442 \u0431\u0435\u0437 \u043A\u0430\u0440\u0442, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u0441\u0432\u043E\u0438 \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u043D\u043D\u044B\u0435 \u043E\u0447\u043A\u0438, \u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0440\u0430\u0443\u043D\u0434\u0430 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0441\u0443\u043C\u043C\u0430\u0440\u043D\u0443\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0438\u0445 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u043A\u0430\u0440\u0442.",
              "\u0417\u0430 \u043E\u0441\u043E\u0431\u043E\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u044B \u043F\u0440\u0435\u043C\u0438\u0438:",
              "- \u0420\u0443\u043C\u043C\u0438 \u0434\u0430\u0451\u0442 200 \u043E\u0447\u043A\u043E\u0432: \u0437\u0430 \u043E\u0434\u0438\u043D \u0445\u043E\u0434 \u0432\u044B \u0434\u043E\u043B\u0436\u043D\u044B \u0432\u043F\u0435\u0440\u0432\u044B\u0435 \u0432\u044B\u043B\u043E\u0436\u0438\u0442\u044C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u0438 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0438\u0437\u0431\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u043E\u0442 \u043A\u0430\u0440\u0442.",
              "- \u0427\u0438\u0441\u0442\u043E\u0435 \u0440\u0443\u043C\u043C\u0438 \u0434\u0430\u0451\u0442 300 \u0432\u043C\u0435\u0441\u0442\u043E 200. \u041D\u0443\u0436\u043D\u043E \u0432\u044B\u0439\u0442\u0438 \u0440\u0443\u043C\u043C\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0438\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u0440\u0443\u043A\u0438, \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044F \u043A \u0443\u0436\u0435 \u043B\u0435\u0436\u0430\u0449\u0438\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F\u043C \u0438 \u043D\u0435 \u0437\u0430\u0431\u0438\u0440\u0430\u044F \u0434\u0436\u043E\u043A\u0435\u0440\u043E\u0432.",
              "- \u0415\u0449\u0451 100 \u043E\u0447\u043A\u043E\u0432 \u0434\u0430\u0451\u0442\u0441\u044F \u0437\u0430 \u0432\u044B\u0445\u043E\u0434 \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043B\u044E\u0431\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u042D\u0442\u0430 \u043F\u0440\u0435\u043C\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u0438 \u0431\u0435\u0437 \u0440\u0443\u043C\u043C\u0438.",
              "\u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0443\u043D\u0434\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043A\u0442\u043E-\u0442\u043E \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0435\u0442 1000, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0441\u0447\u0451\u0442. \u0415\u0441\u043B\u0438 \u043F\u0435\u0440\u0432\u043E\u0435 \u043C\u0435\u0441\u0442\u043E \u043E\u0431\u0449\u0435\u0435, \u0438\u0433\u0440\u0430\u044E\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0443\u043D\u0434.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 S \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043E\u0447\u043A\u0438, E \u2014 \u0440\u0430\u0437\u043C\u0435\u0440\u044B \u0440\u0443\u043A \u0438 \u043E\u0441\u0442\u0430\u0432\u0448\u0435\u0439\u0441\u044F \u043A\u043E\u043B\u043E\u0434\u044B, T \u2014 \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434."),
            rule_section(:blocked, "\u041A\u043E\u0433\u0434\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043A\u043E\u043B\u043E\u0434\u0430",
              "\u041A\u043E\u0433\u0434\u0430 \u043A\u043E\u043B\u043E\u0434\u0430 \u0438\u0441\u0447\u0435\u0440\u043F\u0430\u043D\u0430, \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u0441\u0431\u0440\u043E\u0441 \u043F\u0435\u0440\u0435\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0434\u043B\u044F \u043D\u043E\u0432\u043E\u0433\u043E \u0434\u043E\u0431\u043E\u0440\u0430. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u043F\u043E Shift+D. \u0415\u0441\u043B\u0438 \u0431\u0440\u0430\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435\u043E\u0442\u043A\u0443\u0434\u0430, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C \u0438 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u0431\u0435\u0437 \u0434\u043E\u0431\u043E\u0440\u0430.",
              "\u0415\u0441\u043B\u0438 \u0431\u0440\u0430\u0442\u044C \u043D\u0435\u043E\u0442\u043A\u0443\u0434\u0430 \u0438 \u0434\u0432\u0430 \u043F\u043E\u043B\u043D\u044B\u0445 \u043A\u0440\u0443\u0433\u0430 \u043D\u0438\u043A\u0442\u043E \u043D\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043B \u0438 \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u043B \u043A\u0430\u0440\u0442\u044B \u0441 \u0440\u0443\u043A\u0438, \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F. \u0417\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u043D\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F, \u043D\u043E \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u0440\u0430\u0443\u043D\u0434\u0430 \u0438 \u043F\u0440\u0435\u043C\u0438\u0439 \u0437\u0430 \u0432\u044B\u0445\u043E\u0434 \u043D\u0435\u0442."),
            rule_section(:variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u043F\u0440\u0430\u0432\u0438\u043B",
              "\u041F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0435 \u043D\u0438\u0436\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u0412\u0441\u0451 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043F\u0440\u0435\u0436\u043D\u0438\u043C."),
            rule_section(:limits, "\u041D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u043E\u0440\u043E\u0433 \u0438 \u0446\u0435\u043B\u044C \u043F\u043E \u043E\u0447\u043A\u0430\u043C",
              "\u0412\u043C\u0435\u0441\u0442\u043E 30 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0437\u043D\u0430\u0447\u0438\u0442\u044C \u0434\u0440\u0443\u0433\u0443\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F. \u041F\u043E\u043A\u0430 \u0432\u044B \u043D\u0435 \u0432\u044B\u043B\u043E\u0436\u0438\u0442\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043D\u0430 \u043D\u0443\u0436\u043D\u0443\u044E \u0441\u0443\u043C\u043C\u0443, \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0442\u044C \u043A \u0441\u0442\u043E\u043B\u0443 \u0438 \u0431\u0440\u0430\u0442\u044C \u0441\u0431\u0440\u043E\u0441 \u043D\u0435\u043B\u044C\u0437\u044F.",
              "\u0426\u0435\u043B\u044C \u043F\u0430\u0440\u0442\u0438\u0438 \u0442\u043E\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0441 1000 \u043D\u0430 \u0434\u0440\u0443\u0433\u043E\u0435 \u0447\u0438\u0441\u043B\u043E. \u0418\u0442\u043E\u0433 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u043B\u0438\u0448\u044C \u043F\u043E \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u0438 \u0440\u0430\u0443\u043D\u0434\u0430."),
            rule_section(:discard, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0434\u043E\u0431\u043E\u0440\u0430 \u0438 \u0441\u0431\u0440\u043E\u0441\u0430",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u0441 \u0434\u043E\u0441\u0442\u0443\u043F\u043E\u043C \u0442\u043E\u043B\u044C\u043A\u043E \u043A \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u043E\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442:",
              "- \u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044C \u0431\u0440\u0430\u0442\u044C \u0431\u043E\u043B\u0435\u0435 \u0440\u0430\u043D\u043D\u0438\u0439 \u0441\u0431\u0440\u043E\u0441. D \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u0441\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B, Shift+D \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043F\u0438\u0441\u043E\u043A, \u043D\u0430\u0447\u0438\u043D\u0430\u044F \u0441 \u043D\u043E\u0432\u0435\u0439\u0448\u0435\u0439. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 Enter: \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043D\u0435\u0439 \u0432\u044B \u0437\u0430\u0431\u0435\u0440\u0451\u0442\u0435 \u0432\u0441\u0435 \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u043D\u044B\u0435 \u043F\u043E\u0437\u0436\u0435. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432\u044B\u0431\u043E\u0440 \u0442\u0440\u0435\u0442\u044C\u0435\u0439 \u0434\u0430\u0451\u0442 \u0442\u0440\u0435\u0442\u044C\u044E, \u0432\u0442\u043E\u0440\u0443\u044E \u0438 \u043F\u0435\u0440\u0432\u0443\u044E. \u0415\u0441\u043B\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u043E\u0434\u043D\u0430 \u043A\u0430\u0440\u0442\u0430, Shift+D \u0431\u0435\u0440\u0451\u0442 \u0435\u0451 \u0441\u0440\u0430\u0437\u0443.",
              "- \u0417\u0430\u043F\u0440\u0435\u0442\u0438\u0442\u044C \u0432\u0437\u044F\u0442\u0438\u0435 \u0441\u0431\u0440\u043E\u0441\u0430. \u0422\u043E\u0433\u0434\u0430 \u0431\u0435\u0440\u0438\u0442\u0435 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B, \u0430 \u0432 \u043A\u043E\u043D\u0446\u0435 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Delete.",
              "- \u0423\u0431\u0440\u0430\u0442\u044C \u0441\u0431\u0440\u043E\u0441 \u0441\u043E\u0432\u0441\u0435\u043C. \u041F\u043E\u0441\u043B\u0435 \u0434\u043E\u0431\u043E\u0440\u0430 \u0438 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0435\u0439 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0435 \u0445\u043E\u0434 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435\u043C Shift+F. \u0412\u0441\u0451 \u043D\u0435\u0441\u044B\u0433\u0440\u0430\u043D\u043D\u043E\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0443 \u0432\u0430\u0441."),
            rule_section(:identities, "\u0421\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u0430\u0440\u0442",
              "\u042D\u0442\u0430 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u0438\u0437 \u0442\u0440\u0451\u0445 \u0438\u043B\u0438 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u0430\u0440\u0442, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0442\u0440\u0451\u0445 \u0434\u0435\u0432\u044F\u0442\u043E\u043A \u0442\u0440\u0435\u0444. \u041A\u0430\u0436\u0434\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0442\u0430\u043A\u043E\u0433\u043E \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u0441\u0442\u043E\u0438\u0442 \u043D\u0430 10 \u043E\u0447\u043A\u043E\u0432 \u0431\u043E\u043B\u044C\u0448\u0435 \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E. \u041D\u0430\u0434\u0431\u0430\u0432\u043A\u0430 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u043F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u043C \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0438."),
            rule_section(:rounding, "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0431\u0435\u0437 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u044F",
              "\u0415\u0441\u043B\u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435, \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F:",
              "- \u0414\u0432\u043E\u0439\u043A\u0438 \u2014 \u0434\u0435\u0432\u044F\u0442\u043A\u0438 \u0441\u0442\u043E\u044F\u0442 \u043F\u043E \u0441\u0432\u043E\u0435\u043C\u0443 \u0447\u0438\u0441\u043B\u0443, \u0430 \u043D\u0435 \u043F\u043E 5.",
              "- \u0422\u0443\u0437 \u043F\u0435\u0440\u0435\u0434 \u0434\u0432\u043E\u0439\u043A\u043E\u0439 \u0441\u0442\u043E\u0438\u0442 1, \u0432 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F\u0445 \u0438 \u043D\u0430 \u0440\u0443\u043A\u0435 \u2014 11.",
              "- \u0414\u0435\u0441\u044F\u0442\u043A\u0438 \u0438 \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u0438 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0441\u0442\u043E\u044F\u0442 10.",
              "- \u0414\u0436\u043E\u043A\u0435\u0440 \u043D\u0430 \u0440\u0443\u043A\u0435 \u0441\u0442\u043E\u0438\u0442 20."),
            rule_section(:manipulation, "\u041F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0439 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435",
              "\u0415\u0441\u043B\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0430 \u043F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0439\u043A\u0430, \u043C\u043E\u0436\u043D\u043E \u043C\u0435\u043D\u044F\u0442\u044C \u0443\u0436\u0435 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u0445\u043E\u0434\u0443 \u043D\u0443\u0436\u043D\u043E \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0434\u043E\u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443, \u0430 \u0432\u0430\u0448\u0435 \u043F\u0435\u0440\u0432\u043E\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435 \u0443\u0436\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043E. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 C, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u0438 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u043D\u043E\u0433\u043E \u043C\u0435\u043D\u044E \u0435\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F: \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435, \u0432\u0437\u044F\u0442\u0438\u0435 \u0446\u0435\u043B\u0438\u043A\u043E\u043C \u0438\u043B\u0438 \u0432\u0437\u044F\u0442\u0438\u0435 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u043A\u0430\u0440\u0442.",
              "\u0417\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0432 \u0434\u0440\u0443\u0433\u043E\u043C \u043C\u0435\u0441\u0442\u0435. \u0412\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u0437\u0430\u0432\u0438\u0441\u044F\u0442 \u043E\u0442 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F:",
              "- \u0418\u0437 \u0440\u044F\u0434\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u0437\u044F\u0442\u044C \u043A\u0440\u0430\u0439\u043D\u044E\u044E \u043A\u0430\u0440\u0442\u0443, \u0435\u0441\u043B\u0438 \u043E\u0441\u0442\u0430\u043D\u0443\u0442\u0441\u044F \u0445\u043E\u0442\u044F \u0431\u044B \u0442\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0438\u0437 4, 5, 6, 7 \u0447\u0435\u0440\u0432\u0435\u0439 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u043A\u0443 \u0438\u043B\u0438 \u0441\u0435\u043C\u0451\u0440\u043A\u0443.",
              "- \u0418\u0437 \u0433\u0440\u0443\u043F\u043F\u044B \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u0430\u0440\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u043E\u0434\u043D\u0443 \u043A\u0430\u0440\u0442\u0443.",
              "- \u0426\u0435\u043B\u0438\u043A\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u0431\u0435\u0437 \u0434\u0436\u043E\u043A\u0435\u0440\u0430. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u0435 \u0435\u0433\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0435\u0439 \u043A\u0430\u0440\u0442\u043E\u0439, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0432\u0437\u044F\u0442\u044C \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435.",
              "\u0423\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u043A\u0430\u0440\u0442 \u043D\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u043C\u0435\u043D\u044F\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0434\u0436\u043E\u043A\u0435\u0440\u0430.",
              "\u0414\u043B\u044F \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u044F \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0432 \u043C\u0435\u043D\u044E, \u0437\u0430\u0442\u0435\u043C \u0432\u0442\u043E\u0440\u043E\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435. \u0412\u043C\u0435\u0441\u0442\u0435 \u043E\u043D\u0438 \u0434\u043E\u043B\u0436\u043D\u044B \u0434\u0430\u0442\u044C \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0440\u044F\u0434\u044B 4, 5, 6 \u0447\u0435\u0440\u0432\u0435\u0439 \u0438 7, 8, 9 \u0447\u0435\u0440\u0432\u0435\u0439 \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u044E\u0442\u0441\u044F, \u0430 \u043C\u0435\u0436\u0434\u0443 \u0440\u044F\u0434\u0430\u043C\u0438 \u0441 \u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u043E\u0439 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u043D\u0435\u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0439 \u0440\u0430\u0437\u0440\u044B\u0432.",
              "\u041A\u0430\u0436\u0434\u0430\u044F \u0437\u0430\u0431\u0440\u0430\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430, \u043D\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0437\u0430\u043D\u043E\u0432\u043E \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0445\u043E\u0434\u0430, \u0441\u0442\u043E\u0438\u0442 300 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432. \u0422\u0430\u043A \u0436\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0437\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u0434\u0436\u043E\u043A\u0435\u0440. \u0414\u0432\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043A\u0430\u0440\u0442\u044B \u2014 \u0448\u0442\u0440\u0430\u0444 600. \u041F\u043E\u0441\u043B\u0435 \u0448\u0442\u0440\u0430\u0444\u0430 \u0438\u0445 \u043C\u043E\u0436\u043D\u043E \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0432 \u0440\u0443\u043A\u0435 \u0438 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u0438\u043C\u0438 \u043E\u0431\u044B\u0447\u043D\u043E. \u0421\u0431\u0440\u043E\u0441 \u0437\u0430\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0439 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u043E\u0439.",
              "\u041F\u0440\u0438 \u0432\u0437\u044F\u0442\u0438\u0438 \u0441\u043E \u0441\u0442\u043E\u043B\u0430 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u0432\u044B\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0438\u0437 \u0432\u0430\u0448\u0435\u0433\u043E \u0441\u0447\u0451\u0442\u0430; \u043F\u0440\u0438 \u043D\u043E\u0432\u043E\u0439 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u0435 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043D\u043E\u0432\u0430. \u0421\u0430\u043C\u043E \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435 \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u0434\u0430\u0451\u0442. \u0412\u0437\u044F\u0442\u0438\u0435 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0441\u043E \u0441\u0442\u043E\u043B\u0430 \u0438\u0441\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u043F\u0440\u0435\u043C\u0438\u044E \u0437\u0430 \u0447\u0438\u0441\u0442\u043E\u0435 \u0440\u0443\u043C\u043C\u0438."),
            rule_section(:elimination, "\u0418\u0433\u0440\u0430 \u043D\u0430 \u0432\u044B\u0431\u044B\u0432\u0430\u043D\u0438\u0435",
              "\u0417\u0434\u0435\u0441\u044C \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0438\u0440\u0430\u0442\u044C \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u043C\u0435\u043D\u044C\u0448\u0435 \u043E\u0447\u043A\u043E\u0432. \u0412\u044B\u043A\u043B\u0430\u0434\u043A\u0430, \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u0432\u0437\u044F\u0442\u0438\u0435 \u0441\u043E \u0441\u0442\u043E\u043B\u0430 \u0441\u0447\u0451\u0442 \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442, \u043D\u043E \u043F\u043E\u0440\u043E\u0433 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F. \u0417\u0430\u043A\u043E\u043D\u0447\u0438\u0432\u0448\u0438\u0439 \u0440\u0430\u0443\u043D\u0434 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u043A\u0430\u0440\u0442\u044B, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043E\u0441\u0442\u0430\u0442\u043A\u043E\u0432 \u043D\u0430 \u0440\u0443\u043A\u0430\u0445. \u0428\u0442\u0440\u0430\u0444\u044B \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F, \u0430 \u043D\u0435 \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F.",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u043F\u0440\u0435\u043C\u0438\u0438 \u0437\u0430 \u0440\u0443\u043C\u043C\u0438 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0447\u0443\u0436\u0438\u0445 \u043E\u0441\u0442\u0430\u0442\u043A\u043E\u0432:",
              "- \u041F\u0440\u0438 \u0440\u0443\u043C\u043C\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u0441\u0447\u0438\u0442\u0430\u044E\u0442 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043A\u0430\u0440\u0442\u044B \u0432\u0434\u0432\u043E\u0439\u043D\u0435.",
              "- \u041F\u0440\u0438 \u0447\u0438\u0441\u0442\u043E\u043C \u0440\u0443\u043C\u043C\u0438 \u2014 \u0432\u0442\u0440\u043E\u0439\u043D\u0435.",
              "- \u041F\u0440\u0438 \u0447\u0438\u0441\u0442\u043E\u043C \u0440\u0443\u043C\u043C\u0438 \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u043B\u044E\u0431\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u2014 \u0432\u0447\u0435\u0442\u0432\u0435\u0440\u043E.",
              "\u042D\u0442\u0438 \u043C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u0438 \u043D\u0435 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u044E\u0442 \u0448\u0442\u0440\u0430\u0444\u044B.",
              "\u041F\u0440\u0438 \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u043A\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0441\u0432\u043E\u0435\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0435\u0439\u0441\u044F \u0440\u0443\u043A\u0438.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430 \u0432\u044B\u0431\u044B\u0432\u0430\u044E\u0442 \u0434\u043E\u0441\u0442\u0438\u0433\u0448\u0438\u0435 \u043F\u0440\u0435\u0434\u0435\u043B\u0430 \u043E\u0447\u043A\u043E\u0432, \u043E\u0431\u044B\u0447\u043D\u043E 500. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442. \u0415\u0441\u043B\u0438 \u0432 \u043E\u0434\u043D\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u043F\u0440\u0435\u0434\u0435\u043B\u0430 \u0434\u043E\u0441\u0442\u0438\u0433\u043B\u0438 \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F, \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0438\u0439 \u0441\u0447\u0451\u0442; \u043F\u0440\u0438 \u0435\u0433\u043E \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043F\u043E\u0431\u0435\u0434\u0430 \u043E\u0431\u0449\u0430\u044F."),
            rule_section(:time, "\u0412\u0440\u0435\u043C\u044F \u0438 \u0448\u0442\u0440\u0430\u0444\u044B",
              "\u041F\u0440\u0438 \u0432\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u043E\u043C \u0442\u0430\u0439\u043C\u0435\u0440\u0435 \u043D\u0443\u0436\u043D\u043E \u0443\u0441\u043F\u0435\u0442\u044C \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u044C \u0432\u0435\u0441\u044C \u0445\u043E\u0434. \u041F\u0440\u043E\u0441\u0440\u043E\u0447\u043A\u0430 \u0434\u0430\u0451\u0442 \u0448\u0442\u0440\u0430\u0444 50 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0434\u0430\u043B\u044C\u0448\u0435. \u0415\u0441\u043B\u0438 \u0432\u044B \u0435\u0449\u0451 \u043D\u0435 \u0431\u0440\u0430\u043B\u0438 \u043A\u0430\u0440\u0442\u0443, \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u043E\u0434\u043D\u0443 \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B, \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u0435\u0441\u0442\u044C. \u041F\u043E\u0441\u043B\u0435 \u0443\u0436\u0435 \u0441\u0434\u0435\u043B\u0430\u043D\u043D\u043E\u0433\u043E \u0434\u043E\u0431\u043E\u0440\u0430 \u0432\u0442\u043E\u0440\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u043D\u0435 \u0431\u0443\u0434\u0435\u0442. \u0417\u0430 \u043F\u0440\u043E\u0441\u0440\u043E\u0447\u043A\u0443 \u043A\u0430\u0440\u0442\u0443 \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442.",
              "\u0428\u0442\u0440\u0430\u0444\u044B \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u0440\u043E\u0441\u0440\u043E\u0447\u043A\u0430 \u0441 \u043E\u0434\u043D\u0438\u043C \u043D\u0435\u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043D\u044B\u043C \u0434\u0436\u043E\u043A\u0435\u0440\u043E\u043C \u0441\u043E \u0441\u0442\u043E\u043B\u0430 \u0441\u0442\u043E\u0438\u0442 350 \u043E\u0447\u043A\u043E\u0432. \u0412 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u0438\u0445 \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442, \u0430 \u0432 \u0438\u0433\u0440\u0435 \u043D\u0430 \u0432\u044B\u0431\u044B\u0432\u0430\u043D\u0438\u0435 \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u044E\u0442."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0440\u0443\u043A\u0443 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u0441\u043F\u0438\u0441\u043E\u043A.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u0432\u0437\u044F\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B.",
              "D: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0439 \u0441\u0431\u0440\u043E\u0441.",
              "Shift+D: \u0432\u0437\u044F\u0442\u044C \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u0431\u0440\u043E\u0441\u0430.",
